INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (12, 'Discovery', 'Daft Punk', '法国', '巴黎', 'French House', '8.64', 'Discovery is the second studio album by the French electronic music duo Daft Punk, released on 12 March 2001 by Virgin Records. It marked a shift from the Chicago house style of their first album, Homework (1997), to a house style more inspired by disco, post-disco, garage house, and R&B. Thomas Bangalter of Daft Punk described Discovery as an exploration of song structures, musical forms, and childhood nostalgia, compared to the "raw" electronic music of Homework.', 0, '2024-01', '维珍唱片', '/covers/12-Daft Punk-Discovery.jpg', '61:09', 15, 6, 6.7, 29.7, 7.8, 4, 2, 23.8, 95, 2001, 'Electronic', 'Daft Punk', 41, 10, 6, 4.14, 59652, NULL, 6.4, 'https://pitchfork.com/reviews/albums/2134-discovery/', 'bd3bb36e-16c8-438f-850e-dfbf4d1478f0', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (13, '王菲', '王菲', '中国', '大陆', 'Mandopop', '7.93', '97年的专辑是王菲产后复出，6000万加盟EMI的首张专辑，更是紧接96年大放异彩的大碟《浮躁》之后的作品，给了其受万众瞩目的理由。
