INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (72, '爱如少年', '许巍', '中国', '大陆', 'Alternative Rock, Singer-Songwriter, Pop Rock', '8.62', '历经四年的筛选和反复推敲之后，许巍的第五张专辑终于出炉，这张专辑背后的制作班底几乎囊括了各个国家的顶级音乐制作人。两年的时间中，许巍从100多首歌中逐一选出了这12首歌。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (73, 'Revolver', 'The Beatles', '英国', '利物浦', 'Rock', '9.24', 'A revolver is a repeating handgun with at least one barrel and a revolving cylinder containing multiple chambers for firing. Because most revolver models hold six cartridges before needing to be reloaded, revolvers are commonly called six shooters or sixguns. Due to their rotating cylinder mechanism, they may also be called wheel guns.', 0, NULL, 'Parlophone', '/covers/73-The Beatles-Revolver.jpg', '35:03', 19.2, 5.5, 7.5, 28.5, 9, 2.1, 3.3, 26.5, 101.6, 2017, 'Classic Rock', NULL, 137, NULL, NULL, 4.24, 0, '', 10, 'https://pitchfork.com/reviews/albums/13434-revolver/', 'c7f648e2-9c6d-32df-b5ee-ccab3e696a51', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (74, 'Wall of Eyes', 'The Smile', '英国', '牛津', 'Rock', '7.84', 'Wall of Eyes is the second studio album by the English rock band the Smile, released on 26 January 2024 through XL Recordings. It was recorded in Oxfordshire and Abbey Road Studios, London, with the producer Sam Petts-Davies.', 0, NULL, 'XL Recordings', '/covers/74-The Smile-Wall of Eyes.jpg', '41:29', 16.4, 5, 4.5, 25.5, 8.8, 2, 2, 22, 86.2, 2024, 'Alternative Rock', NULL, 144, NULL, NULL, 3.57, 0, '', 8.5, 'https://pitchfork.com/reviews/albums/the-smile-wall-of-eyes/', '07de8572-913b-4e23-9df0-7fca4bcbf5fe', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (75, '最美妙的旅行', '声音玩具', '中国', '大陆', 'Rock', '8.32', '声音玩具第一张demo专辑', 0, NULL, '草台回声', '/covers/75-声音玩具-最美妙的旅行.jpg', '67:20', 17.8, 6.7, 3.3, 25.8, 8.7, 2, 3.2, 24, 91.5, 2003, 'Art Rock', NULL, 188, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '71a3f193-acaf-4605-a3d8-ad6b6a91bcbb', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (76, '校园民谣', '群星', '中国', '大陆', 'Pop', '8.05', '0', 0, NULL, 'Universal (3)', '/covers/76-群星-校园民谣.jpg', '45:20', 16.8, 6.5, 2, 22, 8, 2, 4.5, 26.8, 88.6, 2004, 'Ballad, Vocal', NULL, 257, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '861c24af-2375-4774-8237-17758ead5f95', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (77, '我爱台湾', '左小祖咒', '中国', '大陆', 'Rock', '7.83', '各位，这张叫《我爱台湾》的唱片，不是什么新鲜玩意儿，都是些老掉牙的调子——从猫王唱过的中文版到街巷里飘着的民谣，没一首是我写的。你们要是指望听点我那些拧巴的噪音、歪歪扭扭的唱腔配着工业音效，可能要失望；但你们要是想在我这把生锈的嗓子里，找点儿过去的影子，或许能捞着点东西。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (78, '台湾', '左小祖咒', '中国', '大陆', 'Rock', '7.4', '这不是一张地理意义上的台湾专辑，而是一场关于记忆重构，专辑里的11首歌，每一首都藏着两层时空：表层是用左小祖咒式的荒诞唱腔重新填词的“傻情歌”，底层却是台湾老歌的旋律骨架——比如《二十岁的某一天》用的是《恰似你的温柔》的动机；《你就是我的》用的是《滚滚红尘》的编曲，《你们说的对对对》用的是《只要为你活一天》的编曲，《你是一个好人》原动机是李宗盛的《结束》，我把它改成了黑色幽默的市井故事：一个老好人生活失意，却还要对着镜子说“我很好”。唱到副歌时，我故意让声音抖得像卡带的录音机，像极了小时候听盗版磁带时的杂音。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (79, 'Master of Reality', 'Black Sabbath', '英国', '伯明翰', 'Rock', '7.83', 'Master of Reality is the third studio album by the English heavy metal band Black Sabbath, released on 6 August 1971 by Vertigo Records. It is regarded by some critics as the foundation of stoner rock and sludge metal. Produced by Rodger Bain, who also produced the band''s prior two albums, Master of Reality was recorded at Island Studios in London from February to April 1971. This would end up being their last album produced by Bain, as production duties would be taken over by guitarist Tony Iommi for their subsequent albums.', 0, NULL, 'Vertigo', '/covers/79-Black Sabbath-Master of Reality.jpg', '34:27', 16, 3, 5, 25.6, 8.6, 3, 2, 22.9, 86.1, 1971, 'Hard Rock', NULL, 23, NULL, NULL, 4.14, 0, '', NULL, NULL, '0cf3156c-ffe4-4086-8d44-79bf267bf66f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (80, '寂寞星空见歌', '李健', '中国', '大陆', 'Mandopop,Contemporary Folk', '8.26', '0', 1, '2011-08-01', NULL, '/covers/80-李健-寂寞星空见歌.jpg', '43:17', 17.8, 7.1, 2.3, 22.9, 9.2, 2, 2.6, 27, 90.9, NULL, 'Chinese Pop', NULL, 224, 27, NULL, NULL, NULL, NULL, NULL, NULL, '1b935d48-c70e-4246-a8e0-f10e752222cf', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (81, '孤独的人是可耻的', '张楚', '中国', '大陆', 'Singer-SongWriter,Folk Rock,Alternative Rock', '8.66', '1994年的春天，市场经济的浪潮席卷而来，空气里浮动着躁动与欲望。站在时代的风口，“魔岩三杰”之一的张楚写下了这首由他词曲编唱一手完成的代表作。他以“恋爱的季节”为隐喻，借鲜花、风与人群的意象，照见个体在亲密与独处之间的摇摆与拉扯。那句“孤独的人是可耻的”表面锋利，实则是对“为迎合而枯萎”的反讽，更是对“像鲜花般骄傲绽放”的生命姿态的深切向往。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (82, 'Savior', 'Green Day', '美国', '罗德奥', 'Rock', '7.91', 'Saviors is the fourteenth studio album by the American rock band Green Day, released on January 19, 2024, through Reprise Records. It received generally positive reviews from critics. The album was promoted through five singles: "The American Dream Is Killing Me", "Look Ma, No Brains!", "Dilemma", "One Eyed Bastard" and "Bobby Sox". The band embarked on the Saviors Tour, a global concert series in support of the album, with 87 shows in six continents.', 0, NULL, 'Reprise Records', '/covers/82-Green Day-Savior.jpg', '37:53', 18.2, 5, 2, 24.8, 8, 2, 3, 24, 87, 2024, 'Alternative Rock', NULL, 65, NULL, NULL, 3.66, 0, '', NULL, NULL, '30bb400f-8f82-4ed1-9c1a-51df0537fcc8', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (83, '爱情的尽头', '伍佰', '中国', '台湾', 'Rock', '7.65', '近一年来, 因为「伍佰的LIVE」专辑的成功, 盛名压力使伍佰重新思考音乐本质与创作的方向; 对外界习惯以音乐分类来标志他们的音乐 (从蓝调摇滚到新台语歌、老歌新编乃至台湾新音乐代表等的桂冠加身),他很清楚知道自己试图寻找的不过是音乐的各种可能罢了。「因为贪心, 才要什么都试。」伍佰说。创作时他是十分「自私」的, 能先满足感动自己的, 才有打动他人的可能。 「爱情的尽头」是伍佰1996年的最新作品, 在一片幡然成风的台语再兴声中, 何以推出一张全部都是国语创作的专辑? 面对长年久居台北都会造成环境语言的更变,无可避免地, 伍佰必须正视他每次创作阶段的不同语言媒介, 才能避开「泛文化」 的陷阱, 不让语言限制住音乐的无边国界。这未尝不是一种预告,藉以抛开live专辑带来的成功包袱, 将一切归零再重新出发。当你想进入这张全新的伍佰的世界时, 记得别被伍佰豪放的歌声或外表骗了:你若不能读出浪人歌中的淡漠其实有最火炽的挽留, 你就无法知道他遥指的爱情尽头 ,不是荒原, 是接近天际线的自由 ;如果说live 祭出一种骇人的群众力量,那么「爱情的尽头」要处理的则是一颗灵魂内在真实的喟赞; 倘若在浪人的情歌里我们听见对世界的愤怒与对抗,那么在「爱情的尽头」里头 ,我们看见了多一些的沉淀, 看见一个明亮、有希望的宽阔世界。', 0, '2026-05-13', '滚石唱片', '/covers/83-伍佰-爱情的尽头.jpg', '44:38', 17.8, 5, 2, 24.2, 8, 2, 2, 23.2, 84.2, 1996, 'Taiwanese Rock', NULL, 169, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5d8af32d-baeb-43e2-8004-24835ba2177a', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (84, 'Breakfast In America', 'Supertramp', '英国', '伦敦', 'Progressive Pop, Pop Rock, Soft Rock, Art Rock', '8.99', 'Breakfast in America is the sixth studio album by the British rock band Supertramp, released on 16 March 1979, by A&M Records. It was recorded from May to December 1978 at The Village Recorder in Los Angeles. It spawned three US Billboard Hot 100 hit singles: "The Logical Song", "Goodbye Stranger", and "Take the Long Way Home". In the UK, "The Logical Song" and the title track were both top 10 hits, the only two the group had in their native country.', 0, '2023-04-12', 'A&M Records', '/covers/84-Supertramp-Breakfast In America.jpg', '44:23', 18.5, 5.6, 3, 28.7, 9.3, 5, 2, 26.8, 98.9, 1979, 'Pop,Rock', NULL, 134, 29, 10, 3.9, 14143, NULL, NULL, NULL, 'bd4aac56-37f5-3d39-a650-bd040757e573', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (85, '生之响往', '刺猬', '中国', '大陆', 'Indie Rock', '8.56', '《生之响往》专辑文案 2018年4月25日，刺猬乐队历经4年潜心创作，近一年制作打磨的全新唱片正式上线。 分割线以下为唱片文案 人生总是要过完才能知道它的样子。 就像一张唱片，总是要听完才能感受其中的起承转合，完整的体会到作者奉出的内心。于是，对于各路音乐平台大佬没有好好做单曲和专辑唱片条目的分类始终耿耿于怀，single（单曲），EP（迷你唱片），LP（全长唱片）这些概念随着数字化，流媒体这些更方便快捷的技术的普遍应用逐渐模糊。而蕴含在概念背后，创作者这样那样的意图与表达对于大多数人来说也变得无关紧要。似乎歌好听就是王道的硬标准并没改变，但一份盖饭和一桌大餐同样是一顿饭所带来的不同体验还是显而易见的。 《生之响往》，刺猬的第八张全长录音室专辑，在此时到来。打开它11首作品，起伏错落简单排列，本本分分，也朴实饱满。即便如此，它却还是这么不同。刺猬曾经是一支极高产的乐队，05年到14年几乎一年一张唱片的发行速度，映衬了一个盛世，也演出了一次次汹涌音乐浪潮中代代风流人物的锋芒勃发。然而生怕来不及的青春洋溢戛然而止，如今这一张新唱片姗姗而来，同样属于刺猬的“全长”上演了时间与生命的相对论，当走过了小半人生，生活的浓度变低，结出的答案变重，与上一张间隔的这四年归为了四个字“生之响往”。四年，又够毕业一次了，很多选择是不是要再面对一次呢？ 之前四首单曲的铺垫，似乎透射着刺猬这次的主题在现实与理想主义间徘徊盘旋，时而通透开朗，时而莽莽撞撞，偶尔无奈问苍天，亦会在不由自主时任性在幻想中流连，宜喜宜嗔。我们的日常里每次打开消息看，不就是这样么？人潮与车流中，普普通通又五颜六色的每一个，日复一日自顾自的循环着。赤裸捶打出来的这些歌，正是，只是生之响，往某个未知的方向。于是首波主打《火车驶向云外，梦安魂于九霄》，这首迈向不惑的颂歌在几秒的留白之后被安排为片尾曲，道完了一成不变的，也还有一扇门设在那里，我们还年轻的很呢。 《生之响往》听完就会知道它讲述了你的那一段故事，而且一切还远未结束。 文：李青', 0, '2023-12-11', '太合麦田（天津）音乐有限公司', '/covers/85-刺猬-生之响往.jpg', '47:12', 17.7, 7.2, 2.3, 25.9, 8, 2, 4.3, 26.8, 94.2, 2018, 'Rock', NULL, 177, 30, 1, NULL, NULL, NULL, NULL, NULL, 'a517bfdf-27ad-49eb-bd6f-1d5e8abb41c1', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (86, 'In the Aeroplane Over the Sea', 'Neutral Milk Hotel', '美国', '洛杉矶', 'Indie Folk, Indie Rock', '8.61', 'In the Aeroplane Over the Sea is the second and final studio album by the American band Neutral Milk Hotel, released on February 10, 1998, by Merge Records. The album is predominantly indie rock and psychedelic folk and is characterized by extensive use of audio distortion and other lo-fi musical elements. Traditional indie rock instruments like the guitar and drums are paired with less conventional instruments like the singing saw and uilleann pipes. The lyrics are surrealistic and opaque, exploring themes that range from nostalgia to love. An important influence for the album was The Diary of a Young Girl, a book of writings from the diary of Anne Frank.', 0, '2024-03-10', 'Merge', '/covers/86-Neutral Milk Hotel-In the Aeroplane Over the Sea.jpg', '39:54', 19.2, 5, 4, 28.5, 8, 2, 2, 26, 94.7, 1998, 'Rock,Folk', 'Robert Schneider', 104, 31, 14, 4.08, 84126, NULL, 10, 'https://pitchfork.com/reviews/albums/5758-in-the-aeroplane-over-the-sea/', '4b01b4c7-bca1-4cd5-b5f7-a4c14f50730b', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (87, 'The Dark Side of The Moon', 'Pink Floyd', '英国', '伦敦', 'Rock', '8.56', 'The Dark Side of the Moon is the eighth studio album by the English progressive rock band Pink Floyd, released on 1 March 1973 by Capitol Records in the US, and on 16 March 1973 by Harvest Records in the UK. Developed during live performances, it was conceived as a concept album that would focus on the pressures faced by the band during their arduous lifestyle, and also deal with the mental health problems of former band member Syd Barrett. New material was recorded in two sessions in 1972 and 1973 at EMI Studios in London.', 0, NULL, 'Pink Floyd Records', '/covers/87-Pink Floyd-The Dark Side of The Moon.jpg', '42:58', 16.5, 6.8, 8.5, 26.2, 8, 2, 2, 24.2, 94.2, 2016, 'Prog Rock', NULL, 117, NULL, NULL, 4.27, 107269, NULL, 9.3, 'https://pitchfork.com/reviews/albums/pink-floyd-the-dark-side-of-the-moon/', '9a4df5ff-faa2-4e62-8542-dc7684e62bf2', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (88, 'Crooked Rain,Crooked Rain', 'Pavement', '美国', NULL, 'Rock', '7.9', 'Crooked Rain, Crooked Rain is the second studio album by American indie rock band Pavement, released on February 14, 1994 by Matador Records. The album saw the band move on towards a more accessible rock sound than that of their more lo-fi debut Slanted and Enchanted and achieve moderate success with the single "Cut Your Hair". The album also saw original drummer Gary Young replaced by Steve West. It was a UK Top 20 hit upon release, although it was not so successful in the US charts.', 0, NULL, 'Matador', '/covers/88-Pavement-Crooked Rain,Crooked Rain.jpg', '42:37', 17.8, 5, 3.1, 24.5, 8.5, 2, 2, 24, 86.9, 2010, 'Alternative Rock', NULL, 115, NULL, NULL, 3.8, 26031, NULL, 10, 'https://pitchfork.com/reviews/albums/6200-crooked-rain-crooked-rain-las-desert-origins/', 'c849edad-3ee3-3523-b2e9-dd4ea3cc55e3', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (89, 'Crime Of The Century', 'Supertramp', '英国', '伦敦', 'Art Rock, Progressive Rock', '9.8', 'Crime of the Century is the third studio album by the British rock band Supertramp, released in October 1974 on A&M Records. Crime of the Century was Supertramp''s commercial breakthrough in many countries, most notably in the UK, Canada and Germany where it peaked in the Top 5 while also making the Top 20 in Australia and France. It was the band''s first album to chart in the United States, reaching No. 38 on the Billboard 200. The single "Dreamer" reached No. 13 on the UK singles chart, but listeners in the United States preferred its B-side, "Bloody Well Right", which peaked at No. 35 on the Billboard Hot 100. "School" was another popular track, particularly on album rock-oriented radio stations. The album was eventually certified Gold in the US in 1977 after the release of Even in the Quietest Moments.... In Canada, it was eventually certified Diamond (sales of one million copies). The album was Supertramp''s first to feature drummer Bob Siebenberg (at the time credited as Bob C. Benberg), saxophone and clarinet player and vocalist John Helliwell, bassist Dougie Thomson, and co-producer Ken Scott. The album has received critical acclaim, including its inclusion in Rolling Stone''s "50 Greatest Prog Rock Albums of All Time".
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (90, '我等就来唱山歌', '交工乐队', '中国', '台湾', 'Folk', '8.46', '台湾经典客家民谣！
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (91, '遇见我', '曹方', '中国', '大陆', 'Folk', '7.93', '2003 年发行第一张全创作专辑《黑色香水》后，虽然宣传低调，但专辑的品质迅速被业内认可，有媒体把她视为是丁薇之后的又一位才气逼人的创作型女歌手。除了自己的唱片之外，曹方为他人创作的实力亦得到不俗口碑，众多艺人竞相邀歌，使这个小女生无生活之忧，乐得不跑宣传，悠闲地活在自己创作的天地里，静悄悄地累积着。两年之后，全新创作专辑《遇见我》面市，曹方包揽全部 11 首歌的词曲创作，才情四溢、内涵丰富的 11 首歌，使她当之无愧地成为创作女生的中坚力量。', 0, NULL, '钛友文化', '/covers/91-曹方-遇见我.jpg', '39:35', 17.3, 4.6, 2, 24.2, 7.7, 2, 3, 26.4, 87.2, 2005, 'Indie Folk', NULL, 221, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'e0570ce0-6841-470d-9d81-363e38aaf6ae', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (92, 'Close To The Edge', 'Yes', '英国', '伦敦', 'Symphonic Prog,Progressive Rock', '8.74', 'Close to the Edge is the fifth studio album by the English progressive rock band Yes, released in the UK on 8 September 1972 and in the US on 13 September 1972, by Atlantic Records. It is their last album until Union (1991) to feature original drummer Bill Bruford, who found the album particularly laborious to make and felt unable to contribute better ideas, which influenced his decision to join King Crimson once recording had finished.', 0, '2024-03-12', 'Attantic', '/covers/92-Yes-Close To The Edge.jpg', '38:52', 18.4, 5, 7, 27.9, 8.4, 2, 2, 25.4, 96.1, 1972, 'Prog Rock', NULL, 161, 33, NULL, 4.19, 41300, NULL, NULL, NULL, '2b9b5b13-5639-4645-b89b-e5ea555f9a65', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (93, '雁渡寒潭', '黄舒骏', '中国', '台湾', 'Pop', '7.9', '黄舒骏——另类歌手的代表人物，他的另类主要体现在歌词上面，独特的角度，与众不同的思维。这是他的第二张专辑，入选了“台湾百大唱片”。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (94, '卡拉OK.台北.我', '张雨生', '中国', '台湾', 'Pop', '8.94', '「LIVE！卡拉OK」是音乐的初始；我们都知道每一张专辑都会有一位叫制作人的角色，去掉那些浮夸不实的形容词後，制作人就成为一个标准的卡拉OK的制造者，专门把卡拉OK的带子做好，然後交给歌手唱。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (95, '两伊战争', '张雨生', '中国', '台湾', 'Pop', '8.06', '张雨生1996年录音室短专辑。匿名旅行者信息：未人工处理，无曲目数据。MusicBrainz: e0135bcb-268f-48f8-80f5-fb5eaf98d654。繁体名：兩伊戰爭。', 0, '2023-11-11', '丰华唱片', '/covers/95-张雨生-两伊战争.jpg', '45:35', 17.8, 5, 3, 24.1, 9.2, 2, 2, 25.6, 88.7, 1996, 'Pop', NULL, 209, NULL, 2, NULL, NULL, NULL, NULL, NULL, 'e0135bcb-268f-48f8-80f5-fb5eaf98d654', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (96, '近人可读', '寸铁', '中国', '大陆', NULL, '7.32', '寸铁2020年录音室专辑。风格：摇滚。郭佳评：「比之前作品悦耳度高很多，好歹算是流畅的作品了。」豆瓣ID：35101591，网易云ID：91171945。', 0, NULL, '太合乐人/Indie Works', '/covers/96-寸铁-近人可读.jpg', '45:01', 16.1, 4, 2, 24.1, 7.2, 2, 3, 22.1, 80.5, 2020, NULL, NULL, 200, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '90ec415b-27e7-4dd8-9d56-c23240824f2d', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (97, 'Heaven Or Las Vegas', 'Cocteau Twins', '英国', NULL, 'Electronic', '8.06', 'Heaven or Las Vegas is the sixth studio album by the Scottish band Cocteau Twins, released on 17 September 1990 by 4AD. Recorded at September Sound in Twickenham, it followed the band''s 1988 album Blue Bell Knoll and was their second release to be issued in the United States through a distribution deal with Capitol Records.', 0, NULL, '4AD', '/covers/97-Cocteau Twins-Heaven Or Las Vegas.jpg', '37:12', 17.2, 4, 5, 26.8, 8.2, 2, 2, 23.5, 88.7, 2014, 'Dream Pop', NULL, 38, NULL, NULL, 4.2, 57556, NULL, 8.3, 'https://pitchfork.com/reviews/albums/19526-cocteau-twins-blue-bell-knollheaven-or-las-vegas/', 'f96df5d2-4ef9-3ef4-a4be-c743802b6f1e', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (98, 'Arrival', 'ABBA', '瑞典', NULL, 'Pop', '8.27', 'Arrival is the fourth studio album by the Swedish pop group ABBA. It was originally released in Sweden on 11 October 1976 by Polar Records. It became one of ABBA''s most successful albums to date, producing three of their biggest hits: "Dancing Queen", "Money, Money, Money" and "Knowing Me, Knowing You". The track "Fernando", which had been released as a single in March 1976, was included on the Australian and New Zealand versions of the album. Arrival was the best-selling album of 1977 in the United Kingdom and was certified gold by the Recording Industry Association of America.', 0, NULL, 'Polar', '/covers/98-ABBA-Arrival.jpg', '36:14', 18.3, 4, 5, 26.9, 8.6, 2, 2, 24.2, 91, 1976, 'Disco', NULL, 2, NULL, NULL, 3.35, 0, '', 8.6, 'https://pitchfork.com/reviews/albums/22600-arrival/', '9f606574-1a02-4e8f-ba37-e969a92acd9a', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (99, '第一册', '子曰', '中国', '大陆', 'Rock', '7.59', '0', 0, NULL, '京文唱片', '/covers/99-子曰-第一册.jpg', '51:07', 16.6, 6, 4, 24.3, 7.6, 2, 2, 21, 83.5, 1997, 'Chinese Rock', NULL, 195, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '507f0847-5a64-423b-9a7e-926ea99c7f8f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (100, '未来的街头', '黄舒骏', '中国', '台湾', 'Pop', '8.16', '这张黄舒骏入伍前的作品集淡化了前两张专辑中浓郁的学院味道，同时也减轻了叙事方面的比重。相应的，原来隐藏在作品背后的一些情绪被放宽、扩大，使得整体风格倾向于抒情和感性。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (101, '蓝色土耳其', '周传雄', '中国', '台湾', 'Pop', '7.7', '我们都在练习快乐的同时，学习跟孤单相处。过不去的时候，请你到周传雄的歌声中稍作停留，闭上眼睛，听见心中的蓝色土耳其！
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (102, 'Famous Last Words', 'Supertramp', '英国', '伦敦', 'Pop Rock', '8.08', '...Famous Last Words..., released in October 1982, is the seventh studio album by the British rock band Supertramp. It was the studio follow-up to 1979''s Breakfast in America and the last album with vocalist/keyboardist/guitarist Roger Hodgson, who left the group to pursue a solo career. Thus, it was the final album to be released by the classic lineup of the band.', 0, '2024-04-02', 'A&M Records', '/covers/102-Supertramp-Famous Last Words.jpg', '43:22', 17.7, 5, 4, 25.1, 8.7, 2.8, 2, 23.6, 88.9, 1982, 'Rock', NULL, 134, 1, 1, 3.96, 0, '', NULL, NULL, 'ddf6b452-fa45-4bd8-9299-1e1bd27d7b54', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (103, 'The Visitors', 'ABBA', '瑞典', NULL, 'Europop, Pop', '8.61', 'The Visitors is the eighth studio album by the Swedish pop group ABBA. It was released on 30 November 1981.', 0, '2024-04-27', 'Polar', '/covers/103-ABBA-The Visitors.jpg', '37:39', 18.5, 6, 4, 27.5, 9, 2, 2, 25.7, 94.7, 1981, 'Pop', NULL, 2, 34, 2, 3.35, 0, '', 8.6, 'https://pitchfork.com/reviews/albums/16577-the-visitors-deluxe-edition/', '6fec847f-21a9-4d33-a7f1-f15e64cab3d7', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (104, 'Sicalyptico', 'Rita Calypso', '西班牙', '马德里', 'Lounge', '8.31', '0', 0, '2019-06-10', 'Siesta', '/covers/104-Rita Calypso-Sicalyptico.jpg', '38:28', 18.3, 5, 3, 25.8, 8.1, 2, 2.8, 26.4, 91.4, 2004, 'Easy Listening', NULL, 126, 35, 15, 3.65, 11, NULL, NULL, NULL, 'c3dccdb3-fac1-4025-85e6-192ce0f96bfb', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (105, 'Please Please Me', 'The Beatles', '英国', '利物浦', 'Merseybeat, Pop Rock', '7.8', '"Please Please Me" is a song by the English rock band the Beatles. It was their second single in the United Kingdom, and their first in the United States. It is also the title track of their first LP, which was recorded to capitalise on the success of the single. It is a John Lennon composition, although its ultimate form was significantly influenced by producer George Martin.', 0, NULL, 'Parlophone', '/covers/105-The Beatles-Please Please Me.jpg', '36:16', 17.8, 4, 2, 24.8, 8.1, 2, 2, 25.1, 85.8, 2017, 'Beat', NULL, 137, 36, NULL, 3.35, 0, '', 9.5, 'https://pitchfork.com/reviews/albums/13419-please-please-me/', 'ade577f6-6087-4a4f-8e87-38b0f8169814', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (106, '雪山白凤凰', '深山', '中国', '大陆', 'Melodic Black Metal, Post-Metal', '7.85', '0', 0, '2024-03-25', '独立发行', '/covers/106-深山-雪山白凤凰.jpg', '43:00', 17, 6, 3, 24.6, 8, 2, 2, 23.8, 86.4, 2024, 'Metal', '深山', 239, 37, 16, NULL, NULL, NULL, NULL, NULL, 'ca26e8d3-4c3a-401c-a9d5-4e26e7c6d09d', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (107, 'Funeral', 'Arcade Fire', '加拿大', '蒙特利尔', 'Indie Rock,Chamber Pop', '8.58', 'Funeral is the debut studio album by Canadian indie rock band Arcade Fire, released on September 14, 2004 by Merge Records. Preliminary recordings for Funeral were made during the course of a week in August 2003 at the Hotel2Tango in Montreal, Quebec, and the recording was completed later that year all in an analogue recording format. Its lyrics draw upon themes of death, change, and the loss of childhood innocence, inspired by the recent passing of several bandmates'' family members during its production. The first half of the album, dubbed the ''Neighborhood'' suite, centres around a town struggling with a power outage in the middle of winter, based on personal experience during the North American ice storm of 1998.', 0, '2024-03-26', 'Rough Trade', '/covers/107-Arcade Fire-Funeral.jpg', '47:56', 17.5, 4, 4, 30, 8.3, 3.4, 2, 25.2, 94.4, 2004, 'Rock,Pop', 'Arcade Fire', 16, 38, 17, 3.93, 53001, NULL, 9.7, 'https://pitchfork.com/reviews/albums/452-funeral/', '26cdc327-38f2-4200-b5dc-f2fa0e13fcfe', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (108, '马秋峰', '王梵瑞', '中国', '大陆', 'Folk,Pop', '7.4', '也不知道在这个当下的时代，作为一个写作者如何不遗憾的出一张作品专辑!也不知道还有多少人会专注地认真听完一张60分钟左右的唱片。 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (109, '冷血动物', '谢天笑', '中国', '大陆', 'Grunge,Alternative Rock', '8.0', '冷血动物乐队灵魂人物谢天笑于1990年初开始创作音乐.1994年底为电影《越南姑娘》创作歌曲《你不象》。1995年11月组建乐队“出家的猎人”并于1995年底在《摇滚北京 III 》合辑中录制单曲“诉说因果”。1996年乐队应邀参加贵州人民广播电台举办的为“希望工程”募捐的大型义演活动。1997年4月吉他手谢天笑找来刚刚从部队复员的贝司手李明（后来加入鼓手武锐）重新组成乐队并取名“冷血动物乐队”。', 0, '2016-09-18', '京文唱片', '/covers/109-谢天笑-冷血动物.jpg', '53:42', 17.5, 6, 2, 25.3, 8.2, 2, 2.8, 24.2, 88, 2000, 'Rock', NULL, 275, 40, 1, NULL, NULL, NULL, NULL, NULL, '5b0a2635-b676-4167-b5c0-4cd96c9fcf84', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (110, '只有一个愿望', '谢天笑', '中国', '大陆', 'Hard Rock', '8.1', '中国摇滚自从上世纪80年代末期出现在华夏大地，至今已有20余年的历史。长久以来，摇滚乐作为当代世界流行音乐场景中最灿烂的一道风景，吸引了无数强调自我，追逐个性的音乐青年。 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (111, '第三只眼', '郑钧', '中国', '大陆', 'Alternative Rock,Art Rock', '8.61', '1997年1月，与宝丽金合作的第一张专辑《第三只眼》正式发行。在九五、九六两年中国流行乐坛始终处于低谷的情况下，新专辑一上市便引起轰动，其主打单曲《天下没有不散的筵席》蝉连五周全国电台总排行榜冠军，《第三只眼》发行了短短两个月的时间，销量已达五十万张！为此，世界著名的音乐杂志 "BILLBOARD"在九七年二、三、六月号上发表了专栏文章和多幅照片介绍这位不同寻常的亚洲歌手，使郑钧成为登上"BILLBOARD"的第一位中国歌星。至此，郑钧在中国歌坛有了新的不可取代的地位。继而《第三只眼》于1997年5月在香港、日本和东南亚同步发行，至此，郑钧的音乐开始向全世界扩展。1998年初，经全国及整个东南亚华语地区听众投票选举，郑钧荣获1997年度"CHANNEL V"颁发"神州最佳男歌手"奖项，成为了该奖设立以来，第一位获得此殊荣的大陆歌手。', 0, '2011-07', '非池中', '/covers/111-郑钧-第三只眼.jpg', '47:03', 18.2, 6.6, 4, 26.8, 8.7, 2.4, 2.7, 25.3, 94.7, 1997, 'Rock', '方无行', 287, 42, 1, NULL, NULL, NULL, NULL, NULL, 'f85d267f-4e0a-4425-9883-836a81018876', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (112, 'Now & Then', 'Carpenters', '美国', '加利福尼亚', 'Pop,Soft Rock', '7.67', 'Now & Then is the fifth studio album by the American music duo the Carpenters, released on May 1, 1973. The album reached No. 2 on the Billboard Top LPs & Tape chart on July 21, 1973, and ranked No. 20 on the Cash Box year-end pop albums chart. The title, suggested by Karen and Richard''s mother Agnes, was taken from a leftover song that did not appear on the album.', 1, '2024-03', 'A&M', '/covers/112-Carpenters-Now & Then.jpg', '22:42', 18, 5, 2, 23.2, 9.1, 2, 2, 23.1, 84.4, 1973, 'Pop,Rock', 'Richard Carpenter', 33, 43, 10, 3.17, 509, NULL, NULL, NULL, '0a799e52-89ea-4748-be37-070e889bffc9', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (113, '我的小清新', '陈升', '中国', '台湾', 'Indie Pop', '7.84', '2019年，为cnDOTA的TI9征途献上的战歌，又不是暗牧发起，园长合作参与。尽管今年没能讲不朽盾留在黄浦江畔，但也希望我们的祝福能够给与他们力量', 0, '2013-10-21', '滚石唱片', '/covers/113-陈升-我的小清新.jpg', '64:22', 17.1, 6, 4, 23.2, 7.7, 2, 2, 24.2, 86.2, 2013, 'Pop', NULL, 295, 44, 2, NULL, NULL, NULL, NULL, NULL, 'babd7f45-635d-4ad0-8bbe-898386d62868', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (114, 'Even In The Quietest Moments', 'Supertramp', '英国', '伦敦', 'Progressive Pop,Pop Rock', '7.88', 'Even in the Quietest Moments... is the fifth album by the British rock band Supertramp, released on 8 April 1977. It was recorded mainly at Caribou Ranch in Colorado with overdubs, vocals, and mixing completed at the Record Plant in Los Angeles. This was Supertramp''s first album to use engineer Peter Henderson, who would work with the band for their next three albums as well.', 0, '2023-05-08', 'A&M', '/covers/114-Supertramp-Even In The Quietest Moments.jpg', '43:25', 17.8, 5, 3, 24.3, 8.4, 2, 2, 24.2, 86.7, 1977, 'Pop,Rock', NULL, 134, 45, 10, 3.73, 4761, NULL, NULL, NULL, '40b675af-1750-4903-9a01-a04716b031aa', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (115, 'Crisis? What Crisis?', 'Supertramp', '英国', '伦敦', 'Pop Rock,Progressive Pop', '7.99', 'Crisis? What Crisis? is the fourth studio album by the British rock band Supertramp, released in November 1975 by A&M Records. It was recorded in both London and Los Angeles, marking the group''s first use of American recording studios.', 0, '2024-04-03', 'A&M', '/covers/115-Supertramp-Crisis_ What Crisis_.jpg', '47:14', 17.8, 6, 4, 23.2, 8.5, 2, 2, 24.4, 87.9, 1975, 'Pop,Rock', NULL, 134, 46, 10, 3.64, 3381, NULL, NULL, NULL, '9b515ecb-d7ca-36e4-a34e-259b5b507bc3', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (116, '造飞机的工厂', '张楚', '中国', '大陆', 'Singer-SongWriter,Indie Rock', '8.13', '造飞机的工厂：
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (117, '郑钧=zj', '郑钧', '中国', '大陆', 'Singer-SongWriter,Pop Rock', '8.79', '郑钧加盟EMI百代后的首张专辑将于2001年12月21日在内地正式发行，这是他第四张个人创作专辑。专辑《郑钧》是他费时3年，甚至专程躲到终南 山中填词谱曲才制作完工的。郑钧透露他隐居终南山期间的独特感受：“当我一个人到山里去的时候，我意识到我周围的人是多么的浮躁，大家在这种状态下是不知 道自己要怎么去做的，所以根本也不可能有什么东西创造出来。” 作为内地原创乐坛的优秀音乐人，郑钧对刚刚发行的新专辑寄予了无限厚望。“年初以来我一直在为新专辑做准备，现在经过反复地打磨，已经基本成形，它将会是 我最出色的一张专辑。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (118, 'In Rainbows', 'Radiohead', '英国', '牛津', 'Art Rock,Alternative Rock', '8.43', 'In Rainbows is the seventh studio album by the English rock band Radiohead. It was self-released on 10 October 2007 as a download, followed by a retail release internationally through XL Recordings on 3 December 2007 and in North America through TBD Records on 1 January 2008. It was Radiohead''s first release after their recording contract with EMI ended with their album Hail to the Thief (2003).', 0, '2024-04-08', 'XL Recordings', '/covers/118-Radiohead-In Rainbows.jpg', '42:38', 17.6, 5, 4, 27.5, 8.9, 2, 2, 25.7, 92.7, 2007, 'Rock', 'Nigel Godrich', 122, 49, 1, 4.33, 0, '', 6.2, 'https://pitchfork.com/reviews/albums/10988-in-rainbows-cd-2/', 'd4e08a8b-375d-474d-b960-9aaad7c04d30', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (119, '怒放', '郑钧', '中国', '大陆', 'Pop Rock', '8.04', '“许多年来我一直特别想做一张彻彻底底完全西化的唱片。因为我们以前始终在学习西方的音乐，一直都在追赶。现在我想尝试一下站在与西方音乐站在同一起跑线上是一种什么样的感觉。在音乐中我就用用他们西方的传统乐器-吉他、鼓、贝司等，形式上比较简单但是要传达出一种完整的想法和感觉。”——郑钧
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (120, '赵小雷', '赵雷', '中国', '大陆', 'Folk', '8.43', '一年来 我天上一会地下一晃 刺激
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (122, '红旗下的蛋', '崔健', '中国', '大陆', 'Art Rock, Alternative Rock', '9.59', '1994年: 崔健发行第三张专辑《红旗下的蛋》，其中萨克斯演奏者刘元、吉他手艾迪对此张专辑的制作起到了重要的作用。本张专辑突出了打击乐的三个声部，包含了传统中国打击乐和油桶。在日本，崔健为协作新专辑的发行，在4个城市巡回演出。演出在日本的媒体和观众当中引起巨大反响。同年，崔健在美国西雅图的Bumbershoot音乐节上演唱。', 0, '2015-04-20', '东西音乐', '/covers/122-崔健-红旗下的蛋.jpg', '42:07', 18.3, 8, 6.5, 30, 8.7, 4.3, 3, 26.7, 105.5, 1994, 'Rock', NULL, 202, 18, 1, NULL, NULL, NULL, NULL, NULL, '5a857118-0913-4f39-96c8-2c244a538009', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (123, '一生有你', '水木年华', '中国', '大陆', 'Mandopop,Campus Folk', '8.85', '水木年华—两位毕业于清华大学、酷爱音乐的才子。他们的组合不是偶然的对音乐的执着、对生活的热爱，在清华默然的熏陶中，卢庚戌、李健如约的走在一起，他们从大学中的惺惺相惜到签约后的相得益彰，无不向我们展示着过人的才华与人文的风范。在李健沉静忧郁的嗓音中，冷艳华美的气质瞬间显现，在卢庚戌热忱沙哑的演唱里，往事的追忆扑面而来，令我们的心怦然而动。在他们和谐的编配下，水木年华拥有了自我的光辉。在他们身上，我们同样看到了深厚、和谐、高贵和健康，这些优秀属于水木清华，这些优秀同样也属于这支正积极进取的新组合—水木年华。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (124, '青春正传', '水木年华', '中国', '大陆', 'Mandopop', '7.95', '每首曲目展示了不同的青春情绪主题，呈现不同的曲风和质感。他们忠实的记录了青春带给我们的憧憬和迷惑，阵痛和感动。你们会在这些歌里面，看到我们脆弱而执着的，敏感而真诚的心在跳动。朋友们，这张专辑献给你们，就想把自己剖开一样。当写下这段文案的最后一个字，坐在空荡的房间里，我不知道还能有什么留下来，给自己。', 0, '2011-03-23', '瀚星艺能', '/covers/124-水木年华-青春正传.jpg', '39:32', 17.3, 4.8, 2, 24.6, 8.3, 2, 2.3, 26.2, 87.5, 2002, 'Pop', NULL, 232, 2, 2, NULL, NULL, NULL, NULL, NULL, '986ec3dc-0b17-43cd-b822-5f3eee209245', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (125, 'Cognitive', 'Soen', '瑞典', NULL, 'Progressive Metal,Progressive Rock', '7.43', 'Cognition encompasses mental processes that deal with knowledge. It includes psychological activities that acquire, store, retrieve, transform, or apply information. Cognitions are a pervasive part of mental life, helping individuals understand and interact with the world.', 0, '2024-04-16', 'Spinefarm', '/covers/125-Soen-Cognitive.jpg', '48:39', 16.5, 4, 2, 24.5, 8, 2, 2, 22.7, 81.7, 2012, 'Metal,Rock', 'Martin Lopez', 130, 53, 20, 3.33, 1586, NULL, NULL, NULL, 'f49a475d-215f-4f63-a515-3bc3aab25874', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (126, 'Ride The Lightning', 'Metallica', '美国', '洛杉矶', 'Thrash Metal', '8.73', 'Ride the Lightning is the second studio album by the American heavy metal band Metallica, released on July 27, 1984, by the independent record label Megaforce Records. The album was recorded in three weeks with producer Flemming Rasmussen at Sweet Silence Studios in Copenhagen, Denmark. The artwork, based on a concept by the band, depicts an electric chair being struck by lightning flowing from the band logo. The title was taken from a passage in Stephen King''s novel The Stand, in which a character uses the phrase to refer to execution by electric chair.', 0, '2024-04-16', 'Megaforce', '/covers/126-Metallica-Ride The Lightning.jpg', '47:20', 17.2, 5, 5, 28.8, 8.9, 4, 2, 25.1, 96, 1984, 'Metal', 'Metallica', 93, 54, 16, 4.09, 52025, NULL, 10, 'https://pitchfork.com/reviews/albums/21755-kill-em-allride-the-lightning/', '589ff96d-0be8-3f82-bdd2-299592e51b40', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (127, '为你而来', '李健', '中国', '大陆', 'Contemporary Folk,Mandopop', '8.51', '水木年华前成员李健正式推出自己单飞后的第二张唱片《为你而来》。这也是他签约泰达音像后推出的继《似水流年》后的第二张唱片。 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (128, '想念你', '李健', '中国', '大陆', 'Contemporary Folk,Mandopop', '8.84', '李健，当今乐坛拥有逆流之美的音乐唱作才子，在2007年的这个春天带着他的第三张全新个人创作专辑《李健。想念你》再一次回到您的视线之中。他用最最温暖的声音，给这个有些浮躁的春天带来一点沉静的力量，在这样一种音乐创作被商业目的沦陷而真情匮乏的时期，他的坚持，让整个华语原创乐坛也得到了一丝安慰。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (129, 'Nevermind', 'Nirvana', '美国', '西雅图', 'Grunge, Alternative Rock', '8.54', 'Nevermind is the second studio album and major label debut by American rock band Nirvana, released on September 24, 1991, by DGC Records. It was Nirvana''s first release to feature drummer Dave Grohl. Produced by Butch Vig, Nevermind features a more polished, radio-friendly sound than the band''s prior work. It was recorded at Sound City Studios in Van Nuys, California, and Smart Studios in Madison, Wisconsin, in May and June 1991, and mastered that August at the Mastering Lab in Hollywood, California.', 0, '2011-12-08', 'DGC', '/covers/129-Nirvana-Nevermind.jpg', '42:11', 18.8, 6, 2.2, 27.2, 8.2, 2, 3, 26.5, 93.9, 1991, 'Rock', 'Nirvana,Butch Vig', 105, 56, 1, 4.05, 82569, NULL, 10, 'https://pitchfork.com/reviews/albums/15854-nevermind-20th-anniversary-edition/', 'eccae410-7577-4daa-b602-92d305828331', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (130, '飞出迷楼', '苏紫旭&The Paramecia', '中国', '大陆', 'Progressive Rock', '8.65', '2017年，清歌琢玉，在古希腊的神话中，有一位名为伊卡洛斯的人物。为了困住牛头人身怪弥诺陶洛斯，他与父亲代达洛斯共同建造了一座迷楼。不料，迷楼建得太过精妙，父子二人竟也身陷其中不可脱', 0, '2024-04-24', 'CSCAV', '/covers/130-苏紫旭&The Paramecia-飞出迷楼.jpg', '42:21', 17.8, 5.2, 4, 29.2, 8.4, 2.6, 2.2, 25.8, 95.2, 2017, 'Rock', 'Zachariah Dorne,苏紫旭', 263, 57, 1, NULL, NULL, NULL, NULL, NULL, 'f06b4b6a-71b9-48f4-b404-9ecc2be4e0db', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (131, '菊花夜行军', '交工乐队', '中国', '台湾', 'Chinese Folk Music, Avant-Folk', '9.02', '交工乐队是台湾第一个备受欧洲乐评瞩目的本土乐团。继「我等就来唱山歌」在两千年金曲奖大放异彩后，交工乐队随即参加了欧洲世界音乐节巡迴演出，是台湾第一个获得欧洲重量级乐评瞩目的本土乐团。2001年推出音乐史诗创作「菊花夜行军」。藉农村青年阿成返乡完成自我的故事，描绘90年代的农村现实，并首度呈现外籍新娘的心境。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (137, '泪水与共', '苏紫旭&The Paramecia', '中国', '大陆', 'Progressive Rock,Art Rock', '8.83', '2023年，于我而言，写歌似乎已溶于本能。《泪水与共》在大疫的最后一年完成，是时带着“水泥墙缝里也能生根开花”的姿态，现今又如一阵前途渺茫的风。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (138, 'loveless', 'my bloody valentine', '英国', '伦敦', 'Shoegaze, Noise Pop', NULL, 'Loveless is the second studio album by the Irish rock band My Bloody Valentine. It was released on 4 November 1991 in the United Kingdom by Creation Records and in the United States by Sire Records. The album was recorded between February 1989 and September 1991, with vocalist and guitarist Kevin Shields leading sessions and experimenting with glide guitar technique, non-standard tunings, digital sampling, and meticulous production methods. The band recorded at nineteen different studios and hired several engineers during the album''s prolonged recording, with its final production cost rumoured to have reached £250,000, though this number is disputed by Shields.', 0, '2024-05-08', 'Creation', '/covers/138-my bloody valentine-loveless.jpg', '46:36', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1991, 'Rock', 'Kevin Shields,Colm O''Ciosoig', 98, 63, 1, 4.25, 96161, NULL, NULL, NULL, '2fd724cb-63f0-4c50-a7bc-7a156d3d3f5a', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (139, 'The Fly II', '苍蝇', '中国', '大陆', 'Alternative Rock,Grunge', NULL, '1989年，Varese Sarabande', 0, '2024-05-09', '索尼音乐', '/covers/139-苍蝇-The Fly II.jpg', '47:41', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2001, 'Rock', NULL, 260, 64, 1, NULL, NULL, NULL, NULL, NULL, '7a3f6f97-117a-37c9-a5ab-4130891a246f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (140, '愿爱无忧', '痛仰乐队', '中国', '大陆', 'Alternative Rock ', '7.45', '这支乐队，死磕的时候被扛成大旗，试图和解时又被错认成楷模，时至今日，在竞相催眠的时代里，却偏偏把自己酿成了水，变成了充盈剔透的精神透镜。而你我这些微光，则决定着透镜反射的颜色，决定着精神所能投射出的强度。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (141, '乐与怒', 'Beyond', '中国', '香港', 'Pop Rock,Hard Rock,Pop Metal', '8.57', '2011，国际', 0, '2023-10-18', '滚石唱片', '/covers/141-Beyond-乐与怒.jpg', '48:52', 18.3, 5, 3, 27.3, 8.2, 2, 3.2, 27.3, 94.3, 1993, 'Pop,Rock,Metal', NULL, 20, 66, 22, NULL, NULL, NULL, NULL, NULL, '002c0375-9910-4747-9c75-f43d28ed975f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (142, '花的姿态演唱会经典实录', '陈绮贞', '中国', '台湾', 'Singer-SongWriter', NULL, '05年陈绮贞的花的姿态演唱会
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (143, 'Thick As A Brick', 'Jethro Tull', '英国', '贝德福特', 'Progressive Rock', NULL, 'Thick as a Brick is the fifth studio album by the British rock band Jethro Tull, released on 3 March 1972 on Chrysalis Records. The album consists of a single continuous piece of music, split across the two sides of the original LP record, and was conceived as a parody of concept albums and the progressive rock genre. Its original packaging took the form of a 12-page newspaper, which presented the album as a musical adaptation of an epic poem by a fictional eight-year-old prodigy named Gerald Bostock, although the lyrics were actually written by the band''s frontman Ian Anderson.', 0, '2024-05-17', 'Chrysalis', '/covers/143-Jethro Tull-Thick As A Brick.jpg', '44:19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1972, 'Rock', NULL, 71, 57, 1, NULL, NULL, NULL, NULL, NULL, '9c086722-b727-4565-9f05-dfc35a1f72c0', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (144, 'Dragon New Warm Mountain I Believe in you', 'Big Thief', '美国', '纽约', 'Indie Folk, Folk Rock', NULL, 'Dragon New Warm Mountain I Believe in You is the fifth studio album by the American band Big Thief, released as a double album through 4AD on February 11, 2022. Produced by drummer James Krivchenia, the album features 20 songs which were recorded over five months in five locations across the United States. The album was supported by six singles. It is also the last album to feature bassist and founding member Max Oleartchik before his departure in 2024.', 0, '2024-05-18', '4AD', '/covers/144-Big Thief-Dragon New Warm Mountain I Believe in you.jpg', '80:25', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2022, 'Folk,Rock', 'James Krivchenia', 21, 68, 24, NULL, NULL, NULL, 9, 'https://pitchfork.com/reviews/albums/big-thief-dragon-new-warm-mountain-i-believe-in-you/', '16045a74-d79d-47c0-b69b-b5085da33c0c', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (145, '龙虎人丹', '新裤子', '中国', '大陆', 'New Wave, Synthpop, Alternative Dance, C-Pop', NULL, '新裤子的最新专辑《龙虎人丹》在10月1日正式上市。百变音乐顽童新裤子乐队这次历时4年精心配制的音乐神药《龙虎人丹》的推出，其药效的奇特强劲将再次颠覆流行乐坛!新裤子乐队一直追求的时髦音乐理念在这张最新的专辑《龙虎人丹》中仍然得以继续，而且有过之而无不及。不论是封面的设计、MV的拍摄、人物的造型还是音乐的内容，可以说都被新裤子乐队做到了极致。特别值得一提的是这张专辑的封面一改新裤子乐队往日漫画、黏土动画或者铁皮玩具的形象，乐队三个成员头一次在封面上露了脸，他们时髦的装束和北京市井草根文化的混搭、复古醒目的封面设计特别具有冲击力，令人在众多的唱片中一眼相中！《龙虎人丹》这张新专辑收录了新裤子潜心研制的十支“音乐良药”，流畅的旋律、浪漫超现实的NEW WAVE音乐、中国传统的旋律小调被拿来作为歌曲配乐上的“药引”， 非常出色！在《Bye Bye Disco》、《你是我的明星》、《龙虎人丹》等歌曲中，混搭音乐的玩法需要有更综合、更到位的审美素质能力，能拿捏到位的非新裤子乐队莫属！这样的“无疆域”音乐制作玩法才是真正国际化的创作态度。', 0, '2024-05-20', '摩登天空', '/covers/145-新裤子-龙虎人丹.jpg', '39:20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2006, 'Rock,Electronic', NULL, 217, 69, 8, NULL, NULL, NULL, NULL, NULL, '4e6d6779-a067-470a-9ff5-b1d4ca26a3d6', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (146, 'Carrie & Lowell', 'Sufjan Stevens', '美国', '底特律', 'Indie Folk, Singer-Songwriter', '8.51', 'Carrie & Lowell is the seventh studio album by the American musician Sufjan Stevens. It was released on March 31, 2015, by Asthmatic Kitty. It was produced by Stevens, and features guest contributions from Thomas Bartlett, Sean Carey, Casey Foubert, Ben Lester, Nedelle Torrisi, and Laura Veirs.', 0, '2024-05-21', 'Asthmatic Kitty ', '/covers/146-Sufjan Stevens-Carrie & Lowell.jpg', '43:27', 17.9, 8.1, 2, 23.9, 8.1, 2, 4.9, 26.7, 93.6, 2015, 'Folk', 'Sufjan Stevens,Doveman', 133, 70, 3, 2.86, 3515, NULL, 10, 'https://pitchfork.com/reviews/albums/sufjan-stevens-carrie-and-lowell-10th-anniversary-edition/', '395152c9-1ba2-4c44-80ab-5d1488818344', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (147, '这一切没有想象的那么糟', '万晓利', '中国', '大陆', 'Contemporary Folk ', '8.39', '平静孤独快乐幸福
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (148, '浮躁', '王菲', '中国', '大陆', 'Dream Pop,MandoPop', '8.92', '长久以来，对于流行歌手的界定无外乎“大众创造偶像”的所谓市场催生观点。认为流行乐天皇的诞生，是适应听众导向的直接结果。但这并非涵盖流行歌手全部内容的绝对评判。这一点在王菲身上体现得较为突出。王菲作为流行音乐界的抗鼎人物，她的音乐轨迹清晰可循，然而促使其成为流行乐“女皇”的，并不是因循市场的常规结果，而是锐步潮流的领军缘由。至少可以说，她模糊了“引导听众”与“被听众引导”之间的界限。这使得她的音乐先人一步，从而使得受众成为一种歌者的主动。这一点对于一个流行歌者而言，意义重大。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (149, 'The Beatles', 'The Beatles', '英国', '利物浦', 'Pop Rock', '9.31', 'The Beatles were an English rock band formed in Liverpool in 1960. The band comprised John Lennon, Paul McCartney, George Harrison and Ringo Starr. They are regarded as the most influential band in popular music and were integral to the development of 1960s counterculture and the recognition of popular music as an art form. Rooted in skiffle, beat and 1950s rock ''n'' roll, their sound incorporated elements of classical music and traditional pop in innovative ways. They also explored styles ranging from folk and Indian music to psychedelia and hard rock. As pioneers in recording, songwriting and artistic presentation, the Beatles revolutionised many aspects of the music industry and were often publicised as leaders of the era''s youth and sociocultural movements.', 0, '2023-10-12', '苹果音乐', '/covers/149-The Beatles-The Beatles.jpg', '93:43', 19.4, 6.2, 6, 29.3, 8.7, 2, 3, 27.8, 102.4, 1968, 'Rock', 'George Martin,Chris Thomas', 137, 1, 1, 3.21, 30056, NULL, 10, 'https://pitchfork.com/reviews/albums/13432-the-beatles/', '010a156d-7681-42a3-ba5e-829db5a6780d', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (150, 'Jay', '周杰伦', '中国', '台湾', 'MandoPop,Contemporary R&B', '7.97', '2000年，专辑中以古典弦乐伴奏及Band，形成英国式的复古风格，加上西班牙式风格的弦乐演奏，意境极度逼近电影配乐。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (151, 'Thriller', 'Michael Jackson', '美国', '加里', 'Contemporary R&B, Dance-Pop, Pop', '7.92', 'Thriller is the sixth studio album by the American singer and songwriter Michael Jackson. It was released on November 29, 1982, through Epic Records. It was produced by Quincy Jones, who previously worked with Jackson on his album Off the Wall (1979). Recording took place from April to November 1982 at Westlake Recording Studios in Los Angeles, California, with a budget of $750,000. With the ongoing backlash against disco music, Jackson transitioned his sound, with Thriller featuring pop, post-disco, and R&B, while its themes include paranoia, romance, and social consciousness. Paul McCartney appears as the first credited featured artist on a Jackson album.', 0, '2024-05-27', 'Epic', '/covers/151-Michael Jackson-Thriller.jpg', '42:21', 17.7, 4, 2.4, 25.8, 9.3, 2, 2, 23.9, 87.1, 1982, 'R&B,Pop', 'Quincy Jones', 94, 74, 26, NULL, NULL, NULL, 7.2, 'https://pitchfork.com/reviews/albums/11163-thriller-25th-anniversary-edition/', '897b7802-6317-492f-8da1-d94e3bf9cba9', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (152, '带我去月球', '张雨生', '中国', '台湾', 'Mandopop', '8.07', '张雨生创作专辑.制造概念.企划情报。这是张雨生亲手整理的概念文字，我们可以从字里行间听见张雨生心里的话。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (153, 'Back In Black', 'AC/DC', '澳大利亚', '悉尼', 'Hard Rock', '7.85', 'Back in Black is the seventh studio album by Australian rock band AC/DC, released on 25 July 1980, by Albert Productions and Atlantic Records. It was the band''s first album to feature Brian Johnson as lead singer, following the death of their previous vocalist Bon Scott. After the commercial breakthrough of their 1979 album Highway to Hell, AC/DC was planning to record a follow-up, but in February 1980, Scott died from alcohol poisoning after a night out in London. The remaining members of the group considered disbanding, but ultimately chose to continue on and recruited Johnson, who had previously been the vocalist for Geordie.', 0, '2024-05-29', 'Atlantic', '/covers/153-AC_DC-Back In Black.jpg', '41:31', 17.4, 4.5, 2.5, 25.1, 8.7, 2, 2, 24.1, 86.3, 1980, 'Rock', 'Mutt Lange', 3, 41, 1, NULL, NULL, NULL, 8.8, 'https://pitchfork.com/reviews/albums/acdc-back-in-black/', '4bbe3188-d626-4aff-82c0-87d455262f49', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (154, '雨吁', '窦唯', '中国', '大陆', 'Post-Rock, Downtempo', '8.3', '《雨吁》共收录了12首曲目，分别是《静安》、《引》、《禧晤》、《乱战国》、《语虚何以言知》、《雨吁》、《天水》、《山秀谷》、《郑公》、《喜调》、《安》、《尾声再》，光看这些曲名就能猜出整张专辑的古意。在这张灌录于2000年的专辑中窦唯还是以人声来演绎，此后就走向了纯音乐的道路，所以这也是至今窦唯最后一张有歌词的专辑，由于当年他与滚石魔岩产生分歧，这张唱片在录制完成后并没能最终出版。', 0, '2014-08-11', '上海音像', '/covers/154-窦唯-雨吁.jpg', '49:28', 17.7, 5, 5, 25.3, 8.2, 2, 2, 26.1, 91.3, 2006, 'Rock,Electronic', NULL, 253, 75, 8, NULL, NULL, NULL, NULL, NULL, '8410af2e-ff9a-4e6f-b317-e747682fdc0b', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (155, '人人都有一颗主唱的心', '二手玫瑰', '中国', '大陆', 'Rock', '7.07', '2010年，乐队，从来就不是一个人的。然而，中国引进西方摇滚乐至今以来，逐渐形成了主唱大红大紫乐手无人问津的尴尬局面。而且，这种潮流和趋势随着历史的发展变得更为突出且有增无', 1, '2024-05-30', '糖衣文化', '/covers/155-二手玫瑰-人人都有一颗主唱的心.jpg', '26:27', 18, 4, 3, 21.2, 6.5, 2, 2, 21.1, 77.8, 2010, 'Experimental Rock', NULL, 167, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1e677eda-bca1-4b7f-8c3e-a72adc692cd3', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (156, 'The Rise and Fall of Ziggy Stardust and the Spiders from Mars', 'David Bowie', '英国', '伦敦', 'Glam Rock,Pop Rock,Rock Opera', NULL, 'The Rise and Fall of Ziggy Stardust and the Spiders from Mars is the fifth studio album by the English musician David Bowie, released on 16 June 1972 in the United Kingdom through RCA Records. It was co-produced by Bowie and Ken Scott and features Bowie''s backing band the Spiders from Mars, composed of Mick Ronson (guitar), Trevor Bolder (bass) and Mick Woodmansey (drums). It was recorded from November 1971 to February 1972 at Trident Studios in London.', 0, '2024-05-29', 'RCA Victor', '/covers/156-David Bowie-The Rise and Fall of Ziggy Stardust and the Spiders from Mar.jpg', '38:29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1972, 'Rock', 'David Bowie,Ken Scott', 43, 76, 1, NULL, NULL, NULL, 8.2, 'https://pitchfork.com/reviews/albums/21066-five-years-1969-1973/', 'bb7f0f5a-586e-3f90-8665-fdc547aa2a54', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (157, '白日梦蓝', '刺猬', '中国', '大陆', 'Indie Rock, Indie Pop, Jangle Pop', '8.45', '故事开始没有画面，伙伴们跟随音乐来到了另一个世界，这里没有纷争，没有欺骗，没有黑夜，这里有一片蓝天，一望无际的麦田和一群爱做梦的青年。。。在一幅沸腾的青春噪音画卷里，“刺猬”又来了！这张全新专辑从音乐编配到歌词表达，都传递了一只更为成熟的“刺猬”，鼓手石璐的开唱也将带给歌迷意外的惊喜。', 0, '2023-11-02', 'Beijing Modern Sky Culture Development Co.,Ltd.', '/covers/157-刺猬-白日梦蓝.jpg', '53:58', 17.8, 5.7, 2.8, 26.5, 7.8, 2, 3.9, 26.4, 92.9, 2009, 'Rock', NULL, 177, 77, 1, NULL, NULL, NULL, NULL, NULL, '13f88f73-c8f6-49e4-a3f9-385f8b4fcf2a', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (158, '未来的主人翁', '罗大佑', '中国', '台湾', 'Campus Folk, Singer-Songwriter', '8.3', '这张专辑花了九个月才录制完成，《之乎者也》的成功带来了无数的争议和期许，使罗大佑在这段时间遭遇到了极大的压力。“这其实是最惨痛的一张唱片，碰到的挫折，失败的感觉是最多的。”《未来的主人翁从头到尾弥散着一种抑郁苍凉的情绪，相信和作者当时内在面临的矛盾，以及外界充满无力感的时代气氛都有关系。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (159, '爱人同志', '罗大佑', '中国', '台湾', 'New Wave, Singer-Songwriter, Mandopop', '8.13', '在罗大佑推出《家》之后沉寂的几年里，台湾歌坛却是发展到了前所未有的热闹地步，个性化歌手与传唱面极广的流行经典层出不穷，一时让人有耳不暇听之感。就在此时，罗大佑也在苦心创作着企图以全新面貌出现的音乐作品，那首唱到妇孺皆知的“恋曲1990” 使写作于这一阶段，此歌亦促成了《爱人同志》专辑50万张的罗氏个人唱片销售纪录。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (160, 'Awakening from Dukkha', '九宝', '中国', '内蒙古', 'Folk Metal', NULL, '2020年，东亚星光，经过无数次的调试与再三修改后，九宝乐队的首张精选集，终于完成了最后的母带处理，并准备好了与你们正式见面。 这张精选集，由九宝乐队从过往发行的三张专辑中，精心挑选', 0, '2024-06-17', '东亚星光', '/covers/160-九宝-Awakening from Dukkha.jpg', '49:51', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2020, 'Metal', NULL, 165, 80, 16, NULL, NULL, NULL, NULL, NULL, '02f41950-5439-45ca-9d1f-55d5119369f2', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (161, 'Master of Puppets', 'Metallica', '美国', '洛杉矶', 'Thrash Metal', NULL, 'Master of Puppets is the third studio album by American heavy metal band Metallica, released on March 3, 1986, by Elektra Records. Recorded in Copenhagen, Denmark, at Sweet Silence Studios with producer Flemming Rasmussen, it is the band''s final album to feature bassist Cliff Burton. While touring in support of Master of Puppets, he died on September 27, 1986, after the band''s tour bus was involved in an accident in Dörarp, Sweden.', 0, '2024-06-18', 'Elektra', '/covers/161-Metallica-Master of Puppets.jpg', '54:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1986, 'Metal', NULL, 93, 54, 16, NULL, NULL, NULL, 10, 'https://pitchfork.com/reviews/albums/metallica-master-of-puppets/', 'cb100c18-fb29-4828-8d24-2fdbac6d6cff', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (162, 'The Mantle', 'Agalloch', '美国', '波特兰', 'Post-Metal, Folk Metal', NULL, 'The Mantle is the second studio album by American metal band Agalloch. The album was released on August 13, 2002, by The End Records.', 0, '2024-06-19', 'The End', '/covers/162-Agalloch-The Mantle.jpg', '68:53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2022, 'Metal', NULL, 6, 81, 16, NULL, NULL, NULL, NULL, NULL, 'a590708e-1907-47ee-814b-8a3745d7b6fc', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (163, '金陵祭', '黑麒麟', '中国', '大陆', 'Folk Metal, Melodic Black Metal', NULL, '2017年，太合乐人/Indieworks，《金陵祭》 黑麒第二张全长专辑，是首张专辑《哀郢》的题材延续和情感升华之作，悲天悯人转化为沉思求索，源自历史又走出历史，是现实的旁观者又无时不在现实的映照之中。', 0, '2024-06-20', '太合音乐', '/covers/163-黑麒麟-金陵祭.jpg', '44:48', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2017, 'Metal', NULL, 312, 82, 16, NULL, NULL, NULL, NULL, NULL, '0f3bad2c-f7bf-44b3-ae5f-a336210f6f3e', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (164, 'Dopethrone', 'Electric Wizard', '英国', '萨摩赛特', 'Stoner Metal, Doom Metal', NULL, 'Dopethrone is the third studio album by English band Electric Wizard, released on 25 September 2000 by Rise Above Records. Following the release and tour of their previous studio album Come My Fanatics... (1997), the group was asked by Rise Above owner Lee Dorrian to create a follow-up. Vocalist and guitarist Jus Oborn has stated that drug issues and other personal problems led to the production of Dopethrone being a "difficult process". The group entered Chuckalumba Studios in May 2000 with only three tracks written: "Dopethrone", "Funeralopolis", and "We Hate You". The album was recorded in three days. Oborn, who wrote all of the album''s lyrics, spoke of H. P. Lovecraft and Robert E. Howard as influences in his own writing while the group disagreed during the mixing sessions about how the overall record should sound. The music on the album has been described as both doom metal and stoner rock, with influences of British groups like Black Sabbath and Motörhead.', 0, '2024-06-19', 'Rise Above', '/covers/164-Electric Wizard-Dopethrone.jpg', '75:54', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2000, 'Metal', NULL, 55, 83, 16, NULL, NULL, NULL, NULL, NULL, '19c74370-6a04-4565-8d1f-feab2d46825d', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (165, 'Symbolic', 'Death', '美国', NULL, 'Technical Death Metal', NULL, 'Symbolic is the sixth studio album by American death metal band Death, released on March 21, 1995, by Roadrunner Records. The album marked a shift towards melodic death metal, while still retaining elements of technical death metal. It is the only album to feature Bobby Koelble and Kelly Conlon on guitar and bass, respectively, and the second and last album to feature drummer Gene Hoglan.', 0, '2024-06-20', 'Metal Blade Records', '/covers/165-Death-Symbolic.jpg', '50:37', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1995, 'Metal', NULL, 46, 84, 16, 4.15, 0, '', 9.1, 'https://pitchfork.com/reviews/albums/death-symbolic/', '70db5ee7-7004-404e-8fef-77c047c3dc28', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (166, '阿密特', '张惠妹', '中国', '台湾', 'Pop Rock,Mandopop', NULL, '2009年', 0, '2024-06-26', '华纳音乐', '/covers/166-张惠妹-阿密特.jpg', '45:43', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2009, 'Rock,Pop', NULL, 205, 85, 17, NULL, NULL, NULL, NULL, NULL, '94d7ae2e-b5c4-4967-bf04-eda2ae101647', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (167, 'Almighty So 2', 'Chief Keef', '美国', '芝加哥', 'Chicago Drill, Trap, Hardcore Hip Hop', NULL, 'Almighty So 2 is the fifth studio album by American rapper Chief Keef, released on May 10, 2024, by Keef''s label, 43B. It serves as a sequel to Chief Keef''s 2013 mixtape Almighty So, as well as the follow-up to both Keef''s fourth studio album 4Nem (2021), as well as Dirty Nachos (2024), his collaborative commercial mixtape with producer Mike WiLL Made-It. It features guest appearances from Ballout, G Herbo, Lil Gnar, Tierra Whack, Sexyy Red and Quavo. Production was handled primarily by Keef himself, with uncredited co-production from DP Beats, Traxster, Mike WiLL Made-It, Shawn Ferrari, Johnny Juliano, and Bobby Raps, among others.', 0, '2024-05-10', '43B', '/covers/167-Chief Keef-Almighty So 2.jpg', '65:44', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2024, 'Hip Hop', 'Keith Cozart', 36, 86, 27, 3.52, 0, '', 8.4, 'https://pitchfork.com/reviews/albums/chief-keef-almighty-so-2/', 'b79ae52d-ce63-4185-93ab-72494c9769b7', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (168, '城市', '张悬', '中国', '台湾', 'Singer-Songwriter, Mandopop, Acoustic Rock, Pop Rock', NULL, 'In China, a megalopolis is a designation by the government to promote the development of a group of cities through transportation and communication links.', 0, '2012-08', '索尼音乐', '/covers/168-张悬-城市.jpg', '47:49', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.61, 2009, 'Singer-Songwriter, Pop, Rock', NULL, 204, 87, 4, NULL, NULL, NULL, NULL, NULL, '90782b04-4e9b-4c22-880d-84a2a56b72fd', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (169, 'My Life Will', '张悬', '中国', '台湾', 'Folk Pop, Singer-Songwriter, Mandopop', NULL, '2006年，索尼音乐，她是张悬。五年来，
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (170, '皇后大道东', '罗大佑', '中国', '台湾', 'Cantopop', NULL, '1991年，大右音乐，《皇后大道东》是1990年“音乐工厂”正式注册后于隔年年初推出的第一张专辑。这张以粤语创作，集结了梅艳芳，黄沾等多位巨星共同演唱的专辑，成功引发港人讨论香港前途', 0, '2024-07-03', '音乐工厂', '/covers/170-罗大佑-皇后大道东.jpg', '50:28', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1991, 'Pop', NULL, 255, 89, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (171, 'Slippery When Wet', 'Bon Jovi', '美国', '新泽西', 'Hard Rock, Glam Metal', NULL, 'Slippery When Wet is the third studio album by American rock band Bon Jovi, released on August 18, 1986, by Mercury Records in North America and Vertigo Records internationally. It was produced by Bruce Fairbairn, with recording sessions taking place between January and July 1986 at Little Mountain Sound Studios in Vancouver. The album features many of Bon Jovi''s best-known songs, including "You Give Love a Bad Name", "Livin'' on a Prayer", and "Wanted Dead or Alive", resulting in the first glam metal album to have 3 top 10 hits on the Billboard Hot 100 chart. To promote the album, Bon Jovi embarked on the Slippery When Wet Tour, which ran from July 1986 to October 1987.', 0, '2024-07-09', 'Mercury Records', '/covers/171-Bon Jovi-Slippery When Wet.jpg', '43:54', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1986, 'Rock,Metal', NULL, 28, 90, 11, NULL, NULL, NULL, NULL, NULL, '840637fd-d5c1-4ec2-a1c4-a60335c3163d', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (172, 'Before the Applause', '重塑雕像的权利', '中国', '大陆', 'Dance-Punk, Post-Punk', NULL, '2017年，Beijing Modern Sky Culture Development Co.,Ltd.，像一颗突然放慢了公转速度的天体，八年之后，重塑雕像的权利终于再次跃升于地平线，庞然而迅猛。今日全球同步发行的《Before The Applause》是一张足以', 0, '2024-07-13', '摩登天空', '/covers/172-重塑雕像的权利-Before the Applause.jpg', '58:23', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2017, 'Punk', '重塑雕像的权利', 289, 91, 29, NULL, NULL, NULL, NULL, NULL, '132da5e5-7bb4-4bef-9c68-719296138d24', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (173, '锦上添花', '戴饶', '中国', '大陆', NULL, NULL, '2022年，《中国说唱巅峰对决》是一档说唱音乐竞演类节目。节目聚集乐坛说唱歌手中的佼佼者，打造说唱音乐“巅峰”之境。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (174, '那些你们喜欢的不喜欢的我都喜欢的女孩', '王啸坤', '中国', '大陆', 'Pop Rock,Mandopop', '8.79', '那些你们喜欢的 不喜欢的 我都喜欢的女孩
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (175, '深庭', '葬尸湖', '中国', '大陆', 'Black Metal', NULL, '距《孤雁》之后4年，葬尸湖新作《深庭》终于问世！就像他们给听众一直以来的印象，在保证典型葬尸湖式浓郁氛围的同时，风格上大胆的突破也会让人眼前一亮——但谁也没想到这次的作品竟直接回归到90年代初，大量老式死亡金属和厄运成分的加入，扑面而来的纯正riff以及诡异冰冷的solo让人大呼过瘾。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (176, 'T.N.T.', 'AC/DC', '澳大利亚', '悉尼', 'Hard Rock', NULL, 'T.N.T. is the second studio album by Australian hard rock band AC/DC, released only in Australia and New Zealand on 1 December 1975. This was the band''s first release with bassist Mark Evans and drummer Phil Rudd, although the last two tracks feature George Young and Tony Currenti, both of whom previously appeared on High Voltage.', 0, '2024-07-15', 'Albert Productions', '/covers/176-AC_DC-T.N.T..jpg', '63:18', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1975, 'Rock', 'George Young', 3, 41, 1, NULL, NULL, NULL, NULL, NULL, 'c0f84466-6d72-45bc-8333-34f89b2c8eb5', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (177, '依然', '李健', '中国', '大陆', 'Mandopop', NULL, '改变的 不变的 都来自你熟悉的李健
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (178, '奕秋', '葬尸湖', '中国', '大陆', 'Atmospheric Black Metal, Depressive Black Metal', NULL, '葬尸湖乐队专辑《奕秋》。', 0, '2024-07-18', '瘟疫唱片', '/covers/178-葬尸湖-奕秋.jpg', '55:02', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2007, 'Metal', NULL, 264, 93, 16, NULL, NULL, NULL, NULL, NULL, '067545b6-5faf-45a7-ad16-a5dc07b64d23', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (179, '(What''s The Story)Morning Glory?', 'Oasis', '英国', '曼彻斯特', 'Britpop', NULL, '"Morning Glory" is a song by the English rock band Oasis, written by Noel Gallagher and included on the band''s second album, (What''s the Story) Morning Glory?, in September 1995. It was given a commercial single release only in Australia, New Zealand, and Japan, and it was also a radio single in the United States and Canada. In North America, it was the first song of the album to receive significant play on modern rock radio stations, which "Some Might Say" and "Roll with It" had not achieved.', 0, '2024-07-24', 'Creation', '/covers/179-Oasis-(Whats The Story)Morning Glory_.jpg', '54:03', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1995, 'Rock', 'Owen Morris', 108, 94, 1, NULL, NULL, NULL, 8.2, 'https://pitchfork.com/reviews/albums/oasis-whats-the-story-morning-glory-30th-anniversary-deluxe-edition/', '929281e2-8a13-4c02-9f9e-8d3a1fc046ab', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (180, '你在红楼 我在西游', '群星', '中国', '大陆', 'Rock', NULL, '2008年，糖衣文化，《西游记》、《红楼梦》两部家喻户晓的中国文学名著，在80年代内地拍摄成电视剧后更使观众更深刻的了解这两部著作，成为太多人当代的记忆。作为改革开放后的重要电视巨作', 1, '2024-07-12', '糖衣文化', '/covers/180-群星-你在红楼 我在西游.jpg', '38:41', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2008, 'Rock', NULL, 257, 95, 1, NULL, NULL, NULL, NULL, NULL, '15ef336f-4ff1-423f-a018-637476a217d6', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (181, '13', 'Blur', '英国', '埃塞克斯郡', 'Alternative Rock, Art Rock, Experimental Rock, Neo-Psychedelia', NULL, '13 is the sixth studio album by the English alternative rock band Blur, released on 15 March 1999. Continuing the band''s stylistic shift away from the Britpop sound of their earlier career, 13 explores art rock and electronic styles. Lyrically, the album is darker and more personal than Blur''s previous efforts, being heavily inspired by Damon Albarn''s breakup with long-term girlfriend, Justine Frischmann.', 0, '2024-07-26', 'EMI', '/covers/181-Blur-13.jpg', '66:50', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1999, 'Rock', 'Blur', 27, 96, 1, NULL, NULL, NULL, 9.1, 'https://pitchfork.com/reviews/albums/831-13/', '998a98ae-1602-4b6e-84b8-2ceb927b180c', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (182, 'Trans Europa Express ', 'Kraftwerk ', '德国', '北莱茵-威斯特法伦', 'Progressive Electronic, Electronic', NULL, 'Trans-Europe Express (German: Trans Europa Express) is the sixth studio album by German electronic band Kraftwerk. Recorded in 1976 in Düsseldorf, Germany, the album was released in March 1977 on Kling Klang Records. It saw the group refine their melodic electronic style, with a focus on sequenced rhythms, minimalism, and occasionally manipulated vocals. The themes include celebrations of the eponymous European railway service and Europe as a whole, and meditations on the disparities between reality and appearance.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (183, 'Storm of the Light''s Bane ', 'Dissection', '瑞典', '西约塔兰省', 'Melodic Black Metal', NULL, 'Storm of the Light''s Bane is the second studio album by Swedish black metal band Dissection, released on 17 November 1995 by Nuclear Blast Records. It is the first album with guitarist Johan Norman, who replaced John Zwetsloot.', 0, '2024-07-29', 'Nuclear Blast ', '/covers/183-Dissection-Storm of the Lights Bane .jpg', '43:16', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1995, 'Metal', 'Dissection', 50, 98, 16, NULL, NULL, NULL, NULL, NULL, '28214c6e-12e1-478d-bcab-ce83c30cee5d', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (184, 'Deep Purple in Rock', 'Deep Purple', '英国', '赫特福德郡', 'Hard Rock', NULL, 'Deep Purple in Rock is the fourth studio album by English rock band Deep Purple, released on 5 June 1970. It was the first studio album recorded by the Mark II line-up of Ritchie Blackmore, Ian Gillan, Roger Glover, Jon Lord and Ian Paice.', 0, '2024-07-30', 'Harvest', '/covers/184-Deep Purple-Deep Purple in Rock.jpg', '43:48', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1970, 'Rock', 'Deep Purple', 47, 41, 1, NULL, NULL, NULL, NULL, NULL, '5156ea9f-eb54-4258-bbf0-e3af9219de1f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (185, '美丽岛', '罗大佑', '中国', '台湾', 'Singer-Songwriter ', NULL, '————华语乐坛最伟大的歌手 批判歌手罗大佑回来了
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (186, '安河桥北', '宋冬野', '中国', '大陆', 'Chamber Folk, Singer-Songwriter', NULL, 'Anheqiaobei station is a station on Line 4 of the Beijing Subway. It is the northern terminus of Line 4 and located just outside the northwest corner of the 5th Ring Road. It is the only station on Line 4 built above-ground and has separated platforms.', 0, '2013-08-26', '摩登天空', '/covers/186-宋冬野-安河桥北.jpg', '55:29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2013, 'Folk', NULL, 199, 100, 3, NULL, NULL, NULL, NULL, NULL, 'b808f03e-c8ee-4747-852d-053fa5f8f8ea', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (187, '北方的北方', '万晓利', '中国', '大陆', 'Folk', NULL, '万晓利第三张个人原创专辑，发行于2010年1月。', 0, '2024-08-02', '独立发行', '/covers/187-万晓利-北方的北方.jpg', '62:43', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2010, 'Chinese Folk', NULL, 163, 50, NULL, NULL, NULL, NULL, NULL, NULL, 'ef67d4a0-ba1a-4b17-a9e9-21a2528c7ae6', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (188, '孤雁', '葬尸湖', '中国', '大陆', 'Atmospheric Black Metal Chinese Folk Music, Depressive Black Metal ', NULL, '中国传奇黑暗金属乐队葬尸湖时隔八年之后的第二张全长正式专辑！新专辑《孤雁》在保持乐队一贯独有的气质和编曲结构的基础上并没有去自我复制，长时间的沉淀和思考带来了意识上的突破使得新专辑更加的波澜壮阔并完成了对旧作的超越。更重要的是硬件上的进步和制作团队的专业化让这张新作无论在音质还是声场的宽度、纵深都是《奕秋》时期无法相比的。这张专辑毫无疑问将成为又一张中国黑暗金属经典之作。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (189, '天湖', '施教日', '中国', '大陆', 'Melodic Black Metal ', NULL, '施教日，这支中国地下摇滚阵营中首屈一指的金属乐队，成为了第一支在欧洲发行珍藏限量版黑胶唱片的中国摇滚团体。在这之前，无论是中国的流行艺人还是摇滚乐队，都是从未有过的。也对他们的音乐产生了浓厚的兴趣。经过几次相互友好的接触后，做出了一个十分大胆并且让人振奋的决定，那就是要为施教日乐队在欧洲发行限量版黑胶唱片"Rirual day"！音乐是不分国界和语言的，好的音乐一定会被大众所认同。"LEGION OF DEATH Records"此次能够发行这张名为"Ritual day"的唱片，一是充分肯定了施教日乐队的音乐实力，二也是为了把好的音乐加以推广。并且，在这张唱片发行的一个星期内，限量发行的300张唱片就全部被预定。', 0, '2024-08-12', '号角唱片', '/covers/189-施教日-天湖.jpg', '42:07', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2003, 'Metal', NULL, 218, NULL, 16, NULL, NULL, NULL, NULL, NULL, '90161958-9204-4d3a-acd2-85bdae50b1fb', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (190, '乐上莲花', '李杰', '中国', '大陆', 'Indie Folk', NULL, '2019年，如果说音乐是李杰的信仰,那么《乐上蘧花》就是李杰用歌声对世界的赞美。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (191, '笑傲江湖原声带', '赵季平', '中国', '大陆', NULL, NULL, '2001年，赵季平是第一位进入世界一线古典音乐唱片品牌的中国音乐家，曾以《活着》《霸王别姬》《大红灯笼高高挂》《菊豆》等电影配乐，令西方世界大开眼界，成为得到国际承认的大师', 0, '2006-07-21', NULL, '/covers/191-赵季平-笑傲江湖原声带.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2001, NULL, NULL, 277, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '66f0c9e1-63ec-4d7d-907e-1820516c345e', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (192, '表情', '李杰', '中国', '大陆', 'Indie Folk', NULL, '2026年，我的AI音乐创作集。探索声音的无限可能，留住每一份听觉惊喜。', 0, '2024-08-23', NULL, '/covers/192-李杰-表情.jpg', '37:51', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1993, 'Folk', NULL, 225, 24, 3, NULL, NULL, NULL, NULL, NULL, 'a1c93c79-785d-48f3-a9b2-1f274158bfc7', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (193, '西湖向西杭州演唱会', '王啸坤', '中国', '大陆', 'Pop Rock,Mandopop', NULL, '没有引人注目的外表，没有华丽的铺陈，对自我没有自信却在音乐上有着绝对的自负，王啸坤从起初的腼腆羞涩，靠着自己的实力与坚持，一路稳扎稳打，从美丽的石家庄唱到繁华的上海参加比赛，只是希望能找到一个舞台，自在欢愉地表达他对音乐的热爱。经过了无数的挣扎与磨练，最后，王啸坤唱出了属于自己的未来与梦想，赢得了2006年我型我秀的全国总冠军。 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (194, '西游记原声带', '许镜清', '中国', '大陆', NULL, NULL, '2001年', 0, '2001-01-08', NULL, '/covers/194-许镜清-西游记原声带.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1986, NULL, NULL, 274, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '0145aacc-18df-4b00-a7c6-a630a747eb7d', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (195, '左小祖咒在地安门', '左小祖咒', '中国', '大陆', 'Indie Rock', NULL, '当世纪之初的洪流正将一切不合时宜的声音推向幽暗边缘，左小祖咒以《在地安门》，完成了他艺术生涯里至关重要的一次转身。这张诞生于 2001 年 11 月 11 日的唱片，与《走失的主人》《庙会之旅》一同，稳稳站在中国先锋地下音乐最坚硬的坐标之上 —— 它们同属一类不取悦的作品，带着近乎粗粝的真实与刺人的清醒，像一剂烈性毒药，寻常耳朵难以承受，却能让真正靠近它的人，瞬间被击中灵魂。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (196, '向前走', '林强', '中国', '台湾', 'C-Pop', NULL, '“语言只有被政治势力压迫时，才有附加意义，一旦语言压迫变成遗迹，就会有另一种生态，另一种经济型态的分配出现。”任职于波丽佳音的詹宏志，对新台语歌的兴起作出了这样的注脚。如果说“抓狂歌”是政治压迫下的产物，那么，“向前走”便可以说是打破语言压迫，创造唱片市场分配新局的代表作。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (197, '每一刻都是崭新的', '许巍', '中国', '大陆', 'Alternative Rock, Singer-Songwriter', NULL, '华语乐坛新精神领袖 许巍压轴2004最受期待全新创作专辑 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (198, 'Purple Rain', 'Prince', '美国', '明尼苏达州', 'Rock', NULL, 'Purple Rain is the sixth studio album by American musician Prince, featuring his backing band the Revolution. It was released on June 25, 1984, by Warner Bros. Records as the soundtrack album to the 1984 film of the same name. Purple Rain was musically denser than Prince''s previous albums, emphasizing full band performances, and multiple layers of guitars, keyboards, electronic synthesizer effects, drum machines, and other instruments. Much of the album has a grandiose, synthesized, and psychedelic substance to the production and performances.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (199, 'Living''s Deal', 'Explosicum', '中国', '大陆', 'Thrash Metal', NULL, '2017', 0, '2024-08-30', 'Punishment 18 Records', '/covers/199-Explosicum-Livings Deal.jpg', '28:46', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2017, 'Metal', NULL, 57, 54, 16, 3.26, 0, '', NULL, NULL, 'c67e4b4e-74cf-448d-b57d-f97179d5d67e', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (200, '我知道你离我不远', '陈楚生', '中国', '大陆', 'Mandopop', NULL, '一次成长的蜕变 一段音乐的纪念 ——《我知道你离我不远》
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (201, '忘忧湖', '深山', '中国', '大陆', 'Atmospheric Black Metal, Post-Metal, Blackgaze, Melodic Black Metal', NULL, '2014年，2014年4月，内含深山8首新作的首张全长专辑《忘忧湖》CD版由PEST正式发行。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (202, '水浒传', '赵季平', '中国', '大陆', NULL, NULL, 'Water Margin, also called Outlaws of the Marsh or All Men Are Brothers, is a Chinese novel from the Ming dynasty that is one of the preeminent Classic Chinese Novels. Attributed to Shi Nai''an, Water Margin was one of the earliest Chinese novels written in vernacular Mandarin Chinese.', 0, '2002-07-21', NULL, '/covers/202-赵季平-水浒传.jpg', '48:36', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1997, NULL, NULL, 277, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'b2ecfc99-cf9b-48e1-9b94-b9e043f297f1', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (204, 'American Idiot', 'Green Day', '美国', '罗德奥', 'Rock', NULL, 'American Idiot is the seventh studio album by the American rock band Green Day, released on September 21, 2004, by Reprise Records. The album was produced by Rob Cavallo in collaboration with the group. Recording sessions for American Idiot took place at Studio 880 in Oakland and Ocean Way Recording in Hollywood, both in California, between 2003 and 2004. A concept album, dubbed a "punk rock opera" by the band members, American Idiot follows the story of Jesus of Suburbia, a lower-middle-class American adolescent anti-hero. The album expresses the disillusionment and dissent of a generation that came of age in a period shaped by tumultuous events such as 9/11 and the Iraq War.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (205, 'Siamese Dream', 'The Smashing Pumpkins', '美国', '芝加哥', 'Alternative Rock,Shoegaze, Grunge,Dream Pop', NULL, 'Siamese Dream is the second studio album by the American alternative rock band the Smashing Pumpkins, released on July 19, 1993 in the UK and on July 27, 1993 in the US, by Virgin Records. The album was produced by Butch Vig and frontman Billy Corgan. Despite its recording sessions being fraught with difficulties and tensions, Siamese Dream debuted at number ten on the Billboard 200, and was eventually certified 4× Platinum by the Recording Industry Association of America (RIAA), with the album selling over six million copies worldwide, catapulting the Smashing Pumpkins to mainstream success and cementing them as a significant group in alternative music.', 0, '2024-09-10', 'Hut', '/covers/205-The Smashing Pumpkins-Siamese Dream.jpg', '125:41', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1993, 'Rock', 'Billy Corgan', 143, 107, 1, NULL, NULL, NULL, 8.3, 'https://pitchfork.com/reviews/albums/16059-gish-deluxe-edition-siamese-dream-deluxe-edition/', '388a305f-d2a9-4cd8-af3b-2ddd9eafd486', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (206, 'Ants From Up There', 'Black Country,New Road', '英国', '剑桥', 'Art Rock, Post-Rock, Chamber Pop, Indie Rock', NULL, 'Ants from Up There is the second studio album by the British rock band Black Country, New Road, released on 4 February 2022 on Ninja Tune. Recorded at Chale Abbey on the Isle of Wight, the album was produced by the band''s live sound engineer Sergio Maschetzko, and is the final album to feature lead vocalist and guitarist Isaac Wood, who announced his departure from the band four days prior to the album''s release.', 0, '2024-09-12', 'Ninja Tune', '/covers/206-Black Country,New Road-Ants From Up There.jpg', '58:46', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2022, 'Rock,Pop', 'Sergio Maschetzko', 22, 108, 17, NULL, NULL, NULL, 8.4, 'https://pitchfork.com/reviews/albums/black-country-new-road-ants-from-up-there/', 'e101df5c-52e2-4dca-8a79-8f55986c5249', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (207, '幻象波普星', '刺猬', '中国', '大陆', 'Dream Pop', NULL, '刺猬从来没有一张如此迷幻得美妙的专辑，即使在那张好评如潮的专辑《白日梦蓝》里，我们也找不到《幻象波普星》里那些似乎从天外飘来的美妙的音色。曾经的刺猬解构雕琢了年轻人对青春的困惑和疑虑，如今的刺猬虽已不再也无需再歌颂青春，但他们依旧抱有幻想———崇尚简单音乐的幻想、旋律化心灵颂歌的幻想。如今，他们将这些幻想化作一张唱片呈现到世人耳前，就像他们自己对新专辑的描述一样：“这是一次美好声音的简洁幻想，这是一辆直达温暖的心灵慢车”。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (208, 'Pet Sounds', 'The Beach Boys', '美国', '加利福尼亚', 'Baroque Pop', NULL, 'Pet Sounds is the eleventh studio album by the American rock band the Beach Boys, released on May 16, 1966, by Capitol Records. It was produced, arranged, and primarily composed by Brian Wilson with guest lyricist Tony Asher. Recorded largely between January and April 1966, it furthered the orchestral sound introduced in The Beach Boys Today! (1965). Seeking to expand Phil Spector''s Wall of Sound technique and surpass the Beatles'' Rubber Soul (1965), Wilson''s orchestrations blended pop, jazz, exotica, classical, and avant-garde elements, combining rock instrumentation with layered vocal harmonies, found sounds, and instruments not normally associated with rock. It was their first album in which studio musicians, such as the Wrecking Crew, largely replaced the band on their instruments, and the first in which any rock group abandoned the small-ensemble format for an entire album. Its unprecedented total production cost exceeded $70,000.', 0, '2019-11-12', 'Capitol', '/covers/208-The Beach Boys-Pet Sounds.jpg', '35:01', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1966, 'Pop', NULL, 136, 110, 2, NULL, NULL, NULL, 9.4, 'https://pitchfork.com/reviews/albums/9371-pet-sounds-40th-anniversary/', '7e8a98c2-5847-43dd-891a-c872a850266c', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (209, 'Blue Blood', 'X', '日本', '千叶', 'Heavy Metal, Visual kei, Speed Metal, Power Metal', NULL, 'Blue Blood is the second studio album by Japanese heavy metal band X Japan, then known as simply X. It was released on April 21, 1989, by CBS/Sony as the band''s major label debut. Blue Blood sold more than 700,000 copies, reached number 6 on the Oricon chart and stayed on the chart for more than 100 weeks. The album''s singles would also reach the top five on the chart. In 2007, Rolling Stone Japan ranked Blue Blood number 15 on their list of the "100 Greatest Japanese Rock Albums of All Time". In 2018, readers and professional musicians voted it the best album in the history of hard rock and heavy metal in We Rock magazine''s "Metal General Election".', 0, '2023-11-12', 'Siren Song', '/covers/209-X-Blue Blood.jpg', '65:05', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1989, 'Metal', NULL, 160, 111, 16, NULL, NULL, NULL, NULL, NULL, 'be486f85-6630-42aa-a2c7-6297ea978abb', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (210, '★ [Blackstar]', 'David Bowie', '英国', '伦敦', 'Art Rock', NULL, '国际，2011', 0, '2024-09-26', 'Sony', '/covers/210-David Bowie-★ [Blackstar].jpg', '41:13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2016, 'Rock', 'David Bowie', 43, 112, 1, NULL, NULL, NULL, NULL, NULL, '0018b304-f497-4807-8f4a-043dac4e86f6', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (211, '黄金时代', '达达乐队', '中国', '大陆', 'Pop Rock', NULL, '用啼笑浮华的生活，沉淀出震撼灵魂的音乐。华纳唱片，麦田音乐岁末巨献，达达星途灿烂，成就《黄金时代》。达达乐队全新专辑《黄金时代》。该专辑见证了乐队两年快速成长旅程，其中11首歌曲是从这两年来所创作40多首备选曲目中精心挑选出来的。不但有正在全国各大电台、电视台打榜的先行曲《等待》，还收录了广告曲《无双》。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (214, '2002年的第一场雪', '刀郎', '中国', '大陆', 'Folk Rock', NULL, '歌喉征服全中国的传奇歌手 2004年首张个人专辑 INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (215, '喀什科尔胡杨', '刀郎', '中国', '大陆', 'Folk Rock', NULL, '刀郎2004年专辑《喀什科尔胡杨》，中国民谣/流行。新疆大漠风情的音乐叙事，粗犷嗓音中的西域苍茫。', 0, '2024-10-12', '旭润音乐', '/covers/215-刀郎-喀什科尔胡杨.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2004, 'Folk,Rock', '李宗盛', 175, 113, 24, NULL, NULL, NULL, NULL, NULL, '18ab2a62-7ad3-401c-821d-ad9bdd5bb267', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (216, '刀郎III', '刀郎', '中国', '大陆', 'Folk Rock', NULL, '2023年，旭润音乐，书契以来，代有歌谣。自楚骚唐律，争妍竞畅，而民间性情之响，遂不得列之于诗坛，于是别之曰‘山歌’。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (217, '完美的呻吟', '陈珊妮', '中国', '台湾', 'Indie Pop, Mandopop, Singer-Songwriter, Alternative Rock', NULL, '2000年，陈珊妮的第6张个人专辑《完美的呻吟》终于在一拖再拖之下，确定于3日下午1点在环亚购物广场的FNAC书店展开首卖，并在12月5日正式发行。一向包办个人专辑词曲创作', 0, '2024-10-09', '魔岩', '/covers/217-陈珊妮-完美的呻吟.jpg', '44:12', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2000, 'Pop,Rock', '陈珊妮', 297, 114, 10, NULL, NULL, NULL, NULL, NULL, 'a2fffda9-b707-4118-9b47-3b785ce747f3', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (218, 'Tago Mago', 'Can', '德国', '科隆', 'Krautrock, Psychedelic Rock, Experimental Rock', NULL, 'Tago Mago is a 1971 album by the German krautrock band Can, released in August as a double LP by United Artists Records. It was the band''s first full album to include vocalist Damo Suzuki after the departure of Malcolm Mooney the year prior, though Suzuki had appeared on most tracks on the 1970 compilation album Soundtracks. Tago Mago was recorded between November 1970 and February 1971 at the Can Studio in the Schloss Nörvenich, a medieval castle near Cologne. It was the band''s third album release, including the 1970 compilation album, Soundtracks, though regarded by the band as their second. Their debut album was Monster Movie (1969).', 0, '2024-10-10', 'United Artists Records', '/covers/218-Can-Tago Mago.jpg', '73:05', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1971, 'Rock', NULL, 30, 115, 1, NULL, NULL, NULL, 10, 'https://pitchfork.com/reviews/albums/16075-tago-mago-40th-anniversary-edition/', '433b100d-83b2-4b51-9e34-947f12b2a2cb', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (219, '优雅的刺猬', '魏如萱', '中国', '台湾', 'Mandopop, Indie Pop, Indietronica', NULL, '⊙ 其实你不曾等待过，因为他从来没有离开 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (220, 'Tempo of the Damned', 'Exodus', '美国', '旧金山', 'Thrash Metal', NULL, 'Tempo of the Damned is the sixth studio album by American thrash metal band Exodus. Released on February 2, 2004 via Nuclear Blast, Tempo of the Damned was Exodus'' first studio release since 1992''s Force of Habit. It was the last appearance of longtime vocalist Steve "Zetro" Souza until his return for 2014''s Blood In, Blood Out as well as the last appearance of founding drummer Tom Hunting until 2007''s The Atrocity Exhibition... Exhibit A. The album was also the last studio appearance of guitarist Rick Hunolt until the band''s 2021 album Persona Non Grata, where he made a guest appearance.', 0, '2024-10-17', 'Nuclear Blast', '/covers/220-Exodus-Tempo of the Damned.jpg', '58:07', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2004, 'Metal', 'Andy Sneap', 56, 54, 16, NULL, NULL, NULL, NULL, NULL, 'abe6ece7-ec2d-4eab-9b11-d0899aeca330', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (221, 'Acabou chorare', 'Novos Baianos', '巴西', '萨尔瓦多', 'MPB,Samba', NULL, 'Acabou Chorare is the second studio album by Brazilian rock and MPB group Novos Baianos. The album was released in 1972 by Som Livre, following the group''s moderately successful debut É Ferro na Boneca (1970). During the recording of the album, the group took inspiration from various contemporary artists of the time, such as Jimi Hendrix, João Gilberto, and Assis Valente. In addition, Gilberto heavily influenced the sound of the album, as he served as the group''s mentor during the album''s recording sessions. The album was written and recorded as a response to contemporary Brazilian music of the 1970s, which often dealt with melancholic subject matters, due in part to the ongoing Brazilian military dictatorship.', 0, '2024-10-18', 'Som Livre', '/covers/221-Novos Baianos-Acabou chorare.jpg', '39:29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1972, 'Brazilian Music', 'Eustáquio Sena', 107, 117, 31, NULL, NULL, NULL, NULL, NULL, '2b7fa52f-2123-4d14-b84e-f8a8b23e4cbd', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (222, 'Metal', 'Annihilator', '加拿大', '渥太华', 'Thrash Metal', NULL, 'A metal is a material that, when polished or fractured, shows a lustrous appearance, and conducts electricity and heat relatively well. These properties are all associated with having electrons available at the Fermi level, as opposed to nonmetallic materials which do not. Metals are typically ductile and malleable.', 0, '2024-10-19', 'Steamhammer', '/covers/222-Annihilator-Metal.jpg', '55:02', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2007, 'Metal', 'Jeff Waters', 14, 54, 16, NULL, NULL, NULL, NULL, NULL, 'ac0538ca-e756-44da-ade1-65ffc98e8d49', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (223, 'Die Mensch-Maschine', 'Kraftwerk', '德国', '杜塞尔多夫', 'Synthpop, Electronic', NULL, 'The Man-Machine is the seventh studio album by German electronic music band Kraftwerk. It was released on 19 May 1978 by Kling Klang in Germany and by Capitol Records elsewhere. A further refinement of their mechanical style, the album saw the group incorporate more immediate songwriting and danceable rhythms. The album has a satirical bent to it. It addresses a wide-range of themes from the Cold War, Germany''s fascination with manufacturing, and humankind''s increasingly symbiotic relationship with machines. It includes the singles "The Model" and "The Robots".', 0, '2024-10-20', 'Kling Klang Schallplatten', '/covers/223-Kraftwerk-Die Mensch-Maschine.jpg', '36:13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1978, 'Electronic,Pop', 'Ralf Hütter,Florian Schneider', 81, 118, 32, NULL, NULL, NULL, NULL, NULL, 'ebea06a2-3ffb-331a-b754-b39036c8562e', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (224, 'Dots and Loops', 'Stereolab', '英国', '伦敦', 'Art Pop, Indietronica, Ambient Pop', NULL, 'Dots and Loops is the fifth studio album by English-French rock band Stereolab. It was released on 22 September 1997 and was issued by Duophonic Records and Elektra Records. The band co-produced the album with John McEntire and Andi Toma, and recording took place at their respective studios in Chicago and Düsseldorf. It was produced on Pro Tools, making it the band''s first album to use a Digital Audio Workstation.', 0, '2024-10-21', 'Elektra Records', '/covers/224-Stereolab-Dots and Loops.jpg', '65:55', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1997, 'Pop,Electronic,Ambient Pop', 'The Groop', 132, 119, 33, NULL, NULL, NULL, 9.2, 'https://pitchfork.com/reviews/albums/stereolab-dots-and-loops/', '6ddaeeb3-95a8-4e84-ba18-71e61343ac61', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (225, 'Illinois', 'Sufjan Stevens', '美国', '底特律', 'Chamber Pop, Singer-Songwriter', NULL, 'Illinois is a state in the Midwestern region of the United States. It borders on Lake Michigan to its northeast, the Mississippi River to its west, and the Wabash and Ohio rivers to its south. Of the fifty U.S. states, Illinois has the fifth-largest gross domestic product (GDP), the sixth-largest population, and the 25th-most land area. Its capital city is Springfield in the center of the state, and the state''s largest city is Chicago in the northeast.', 0, '2024-10-24', 'Asthmatic Kitty ', '/covers/225-Sufjan Stevens-Illinois.jpg', '91:13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2005, 'Pop', 'Sufjan Stevens', 133, 120, 2, NULL, NULL, NULL, 9.2, 'https://pitchfork.com/reviews/albums/7514-illinois/', '81866da6-b639-4a8a-b066-9648f6087dad', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (226, '迷藏', '梁博', '中国', '大陆', 'Pop Rock, Mandopop, Singer-Songwriter', NULL, '人越成长越像和自己捉迷藏。你一次次故意让自己找不到自己。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (227, 'Голос сталі (The Voice of Steel)', 'Nokturnal Mortum', '乌克兰', NULL, 'Folk Metal, Pagan Black Metal', NULL, '国际，2011', 0, '2024-10-26', 'Oriana Music', '/covers/227-Nokturnal Mortum-Голос сталі (The Voice of Steel)-caa.jpg', '102:53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2009, 'Metal', NULL, 106, 122, 16, NULL, NULL, NULL, NULL, NULL, '2f5a9cb0-c0ec-4668-8d17-77528ff93cd2', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (228, 'Wild Mood Swings', 'The Cure', '英国', '西萨塞克斯', 'Alternative Rock, Pop Rock', NULL, 'A mood swing is an extreme or sudden change of mood. Such changes can play a positive or a disruptive part in promoting problem solving and in producing flexible forward planning. When mood swings are severe, they may be categorized as part of a mental illness, such as bipolar disorder, where erratic and disruptive mood swings are a defining feature.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (229, '和自己对话', '林俊杰', '中国', '台湾', 'Ambient, Mandopop', NULL, '2015年，JFJ Productions，林俊杰 JJ Lin 实验专辑
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (230, '菲靡靡之音', '王菲', '中国', '大陆', 'Mandopop, Adult Contemporary', NULL, '《菲靡靡之音》是歌手王菲于1995年7月推出的一张国语专辑，共13首歌曲。这张专辑是王菲为了纪念她的偶像邓丽君所出版的一张翻唱碟，众所周知要把邓丽君的歌曲翻唱好并非易事，然而王菲却做到了，这可以说一张非常经典的翻唱专辑。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (231, 'Surf''s Up', 'The Beach Boys', '美国', '加利福尼亚', 'Psychedelic Pop, Progressive Pop', NULL, 'Surf''s Up is the seventeenth studio album by American rock band the Beach Boys, released on August 30, 1971, on Brother/Reprise/Warner Bros. It received largely favorable reviews and reached number 29 on the U.S. record charts, becoming their highest-charting LP of new music in the U.S. since 1967. In the UK, Surf''s Up peaked at number 15, continuing a string of top-40 records that began in 1965.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (232, 'Pop', 'U2', '爱尔兰', '都柏林', 'Alternative Rock, Pop Rock', NULL, 'A*Pop is the upcoming second studio album by the South African singer Tyla. It is scheduled to be released on 24 July 2026 through FAX and Epic Records.', 0, '2024-11-02', 'Island Records', '/covers/232-U2-Pop.jpg', '60:11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1997, 'Rock', 'Flood', 150, 123, 1, NULL, NULL, NULL, 8, 'https://pitchfork.com/reviews/albums/u2-pop/', '0022175d-8fb7-491f-b4cd-6951fce43e48', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (233, 'In Utero', 'Nirvana', '美国', '西雅图', 'Grunge, Noise Rock', NULL, 'In Utero is the third and final studio album by the American rock band Nirvana, released on September 21, 1993, by DGC Records. After breaking into the mainstream with their previous album, Nevermind (1991), Nirvana hired Steve Albini to record In Utero, seeking a more complex, abrasive sound that was reminiscent of their work prior to Nevermind. Although the songwriter, Kurt Cobain, said it was "very impersonal", many songs allude to his personal life, expressing feelings of angst that were prevalent on Nevermind.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (234, 'Motanka', 'Motanka', '乌克兰', NULL, 'Folk Metal', NULL, 'A motanka doll (Ukrainian: мотанка) is a traditional East Slavic cloth doll associated with folk culture in Ukraine. It is typically handmade by winding and tying pieces of fabric without the use of needles or stitching and is often considered both a toy and a symbolic or ritual object.', 0, '2024-11-14', 'Napalm', '/covers/234-Motanka-Motanka.jpg', '57:31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2019, 'Metal', NULL, 97, 80, 16, NULL, NULL, NULL, NULL, NULL, 'c99ec67c-a91b-4ea7-8589-14c85133c12c', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (235, 'Achtung Baby', 'U2', '爱尔兰', '都柏林', 'Alternative Rock, Pop Rock', NULL, 'Achtung Baby ( AHKH-toong) is the seventh studio album by the Irish rock band U2. It was produced by Daniel Lanois and Brian Eno, and was released on 18 November 1991 by Island Records. After criticism of their 1988 documentary film and album Rattle and Hum and a sense of creative stagnation, U2 shifted their direction to incorporate influences from alternative, industrial, and electronic dance music into their sound. Thematically, Achtung Baby is darker, more introspective, and at times more flippant than their previous work. For his lyrics, lead vocalist Bono was partly inspired by the failed marriages of two friends, including U2''s guitarist the Edge.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (236, 'La leyenda de La Mancha', 'Mägo de Oz', '西班牙', '马德里', 'Celtic Metal', NULL, 'La Leyenda de La Mancha is the third studio album by Spanish folk metal band Mägo de Oz, released in 1998. It is a concept album, specifically a modern-day retelling of the Spanish classic Don Quixote. The song "Molinos de Viento" is one of Mägo de Oz''s biggest hits and is often the concluding song in concerts.', 0, '2024-11-15', 'locomotive_records', '/covers/236-Mägo de Oz-La leyenda de La Mancha.jpg', '55:39', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1998, 'Metal', 'Goyo Esteban', 100, 128, 16, NULL, NULL, NULL, NULL, NULL, '3a6d6a0b-0066-4d22-a7c4-aff3fb8484b6', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (237, 'Atom Heart Mother', 'Pink Floyd', '英国', '伦敦', 'Progressive Rock, Psychedelic Rock', NULL, 'Atom Heart Mother is the fifth studio album by the English rock band Pink Floyd. It was released by Harvest on 2 October 1970 in the United Kingdom, and on 10 October 1970 in the United States. It was recorded at EMI Studios in London, and was the band''s first album to reach number 1 in the UK, while it reached number 55 in the US, eventually going gold there.', 0, '2024-11-15', 'Harvest', '/covers/237-Pink Floyd-Atom Heart Mother.jpg', '52:06', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1970, 'Rock', 'Pink Floyd', 117, 129, 1, NULL, NULL, NULL, NULL, NULL, '2c7efdf8-2d9f-37f5-8f01-b71ae38c3ea4', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (238, '笑着哭', '汪峰', '中国', '大陆', 'Singer-Songwriter, Pop Rock', NULL, '汪峰签约华纳唱片的第三张专辑。这张专辑是著名音乐人黄小茂出任华纳唱片制作总监之后的第一张唱片，因此得到格外重视，是从汪峰多首创作歌曲中经六次挑选才最终确定的。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (239, '司命楼兰', '葬尸湖、英吉沙', '中国', '大陆', 'Black Metal', NULL, '2005年，葬尸湖早期作品集《悲赋之秋》与其分支乐队英吉沙早期作品集《司命楼兰》的split合盘发行', 0, '2024-11-15', '瘟疫唱片', '/covers/239-葬尸湖、英吉沙-司命楼兰.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2005, 'Metal', NULL, 265, 92, 16, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (240, 'A Dream in Static', 'Earthside', '美国', '纽黑文', 'Progressive Metal', NULL, 'A Dream in Static is the debut studio album by American post-metal band Earthside. The album was released on October 23, 2015, and produced by David Castillo, in addition to two of the band members Frank Sacramone and Jamie van Dyck.', 0, '2024-11-20', 'Not On Label (Earthside Self-released)', '/covers/240-Earthside-A Dream in Static.jpg', '63:57', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2015, 'Metal', NULL, 53, 131, 16, NULL, NULL, NULL, NULL, NULL, '18981689-6c89-44b1-b1e1-9ed323b06c9b', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (241, 'Filosofem', 'Burzum', '挪威', '卑尔根', 'Atmospheric Black Metal, Ambient', NULL, 'Filosofem (Norwegian for "Philosopheme") is the fourth studio album by Norwegian black metal solo project Burzum. It was recorded in March 1993 and was the last recording before Varg Vikernes was sentenced to prison in 1994; the album was not released until January 1996, however. It was released through Misanthropy Records and Vikernes''s own record label, Cymophane Productions. A music video was made for the song "Dunkelheit" and received airtime on both MTV and VH1.
