INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (244, 'Pulver', 'Lifelover', '瑞典', '斯德哥尔摩', 'DSBM, Post-Punk', NULL, 'Ensign Pulver is a 1964 American Technicolor comedy drama film in Panavision and a sequel to the 1955 film Mister Roberts. The film stars Robert Walker Jr., Burl Ives, Walter Matthau and Tommy Sands and features Millie Perkins, Larry Hagman, Kay Medford, Peter Marshall, Jack Nicholson, Richard Gautier, George Lindsey, James Farentino and James Coco.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (245, '私房歌', '郑智化', '中国', '台湾', 'Folk', NULL, '私房歌，我的私生活。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (246, '星星点灯', '郑智化', '中国', '台湾', 'Folk', NULL, '一次又一次地，郑智化在自己的歌里掏心。坚持着一个创作者该有的敏感和坦白，从“老么的故事”、“单身逃亡”、“堕落天使”、“年轻时代”、“私房歌”一直到“星星点灯”。郑智化就像是一个勇敢的代言人，他藉着犀利的词曲；大胆地剖析了这个时代和他自己。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (247, '如果云知道', '许茹芸', '中国', '台湾', 'Mandopop', NULL, '延续《泪海》的好口碑，季忠平再次为许茹芸量身创作《如果云知道》，并成功写下佳绩；整张专辑由刘天健、Peter Wong、袁惟仁、徐德昌、黄国伦为制作班底空灵的气音唱腔成为许茹芸独树一格的招牌，这是其它歌手难以取代的声音识别，却不是许茹芸诠释歌曲的唯一方式；轻快的《执着》、民谣的《半首歌》、神经质的《你讨厌》…淋漓尽致的声音表现，带着这张专辑入围当届最佳女歌手、最佳国语流行专辑等金曲奖项。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (248, 'Love,Sandy', '林忆莲', '中国', '台湾', 'Mandopop', NULL, '1995年，滚石唱片，《Love, Sandy》为林忆莲加盟滚石唱片的首张专辑，为其缔造了空前的销售纪录。仅仅台湾销量就80万张之多！由香港到台湾发展的女歌手至今没有一个能超越此纪录', 0, '2024-12-11', '滚石唱片', '/covers/248-林忆莲-Love,Sandy.jpg', '41:24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1995, 'Pop', NULL, 229, 2, 2, NULL, NULL, NULL, NULL, NULL, 'c7345f58-a85a-4a53-9ec7-a9611a7ace21', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (249, 'I''m With You', 'Red Hot Chili Peppers', '美国', '洛杉矶', 'Alternative Rock, Funk Rock, Pop Rock, Rap Rock', NULL, 'I''m with You is the tenth studio album by the American rock band Red Hot Chili Peppers. The album was released by Warner Bros. Records on August 26, 2011, in Europe and on August 29, 2011, in the United States. The album made its debut at number one in 18 countries including the United Kingdom, while reaching number two in the United States and Canada.', 0, '2024-12-11', '华纳兄弟', '/covers/249-Red Hot Chili Peppers-Im With You.jpg', '59:16', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2011, 'Rock', NULL, 124, 135, 1, NULL, NULL, NULL, 4, 'https://pitchfork.com/reviews/albums/15761-im-with-you/', '3cd51dc5-4d02-438e-9e51-ed52a333d7e5', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (250, 'Young Fresh Chin II', '夏之禹', '中国', '大陆', 'Conscious Hip Hop, Boom Bap', NULL, '2023年，独立发行，一张生气与残酷并存的嘻哈大碟！
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (251, '何德何能', '黄舒骏', '中国', '台湾', 'Mandopop', NULL, '并不是所有的歌手在人们的心中都能留下深深的印迹，黄舒骏创造的是一种生命中欢欣和悲伤的过程，可以在连绵不绝的歌词中，创造出结结实的生活状态。其中,或有流浪、孤单充满痛苦的岁月，或有横跨80年台湾沧桑历史的人生，后者则更加偏近于史诗的写法。又或者是一张摆在你面前的脸，时而面无表情，时而凄迷。', 0, '2024-12-18', '宏扬国际', '/covers/251-黄舒骏-何德何能.jpg', '53:40', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1992, 'Pop', NULL, 309, 2, 2, NULL, NULL, NULL, NULL, NULL, '603892f6-7138-4261-b5e7-05089c00e25f', 'active');
