INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (253, 'A-Sides', 'Adrianne Lenker & Buck Meek', '美国', '印第安纳波利斯', 'Singer-Songwriter, Indie Folk', NULL, 'A-Sides is a greatest hits album by the American rock band Soundgarden with songs spanning the band''s thirteen-year career. It was released on November 4, 1997, through A&M Records.', NULL, '2024-12-19', '独立发行', '/covers/253-Adrianne Lenker & Buck Meek-A-Sides.jpg', '43:51', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2014, 'Folk', NULL, 5, 137, 3, NULL, NULL, NULL, NULL, NULL, '3918afc1-1abb-4a9f-aedc-e2c9b2ed1d02', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (254, 'B-Sides', 'Adrianne Lenker & Buck Meek', '美国', '印第安纳波利斯', 'Singer-Songwriter, Indie Folk', NULL, 'B-Sides or B-Side may refer to:', NULL, '2024-12-19', '独立发行', '/covers/254-Adrianne Lenker & Buck Meek-B-Sides.jpg', '43:51', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2014, 'Folk', NULL, 5, 137, 3, NULL, NULL, NULL, NULL, NULL, 'ea0262a7-f554-43a8-9a02-5a33afbea0a3', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (255, '虎口脱险', '老狼', '中国', '大陆', 'Mandopop,Folk', NULL, '2002年，华纳音乐，若干年前的过去，在那张《校园民谣》专辑和它所象征的那个轰轰烈烈的校园民谣运动因为无数狗尾续貂之作而每况愈下时，老狼――这个注定和校园民谣有着不解之缘的歌手推出了', 0, '2011-10-21', '华纳音乐', '/covers/255-老狼-虎口脱险.jpg', '47:40', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2002, 'Folk', '高晓松、黄小茂', 258, 138, 3, NULL, NULL, NULL, NULL, NULL, 'eb875bd5-1390-48a3-917c-82dee7747ef4', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (256, 'Songs', 'Adrianne Lenker', '美国', '印第安纳波利斯', 'Singer-Songwriter, Indie Folk', NULL, 'A song is a musical composition performed by the human voice. The voice often carries the melody (a series of distinct and fixed pitches) using patterns of sound and silence. Songs have a structure, such as the common ABA form, and are usually made of sections that are repeated or performed with variation later. A song without instruments is said to be a cappella.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (257, '青春', '王梵瑞', '中国', '大陆', 'Folk,Pop', NULL, '专辑《青春》涉及的音乐主题相对于时下多以情歌为主的流行音乐唱片多了一层内省的深度和话题的广度。青春岁月中的各种情感状态均有触碰：漂泊的孤独-《这座城市》，青春的呐喊—《青春》，幸福的寻觅-《幸福》，成熟前的躁动-《傻东西》，光阴流逝的无奈-《时间一枪打在我身上》，爱情的忧伤-《爱》，欲望的挣扎-《战争》，生活的诘问-《十万个为什么》尽皆包括。这些充满人文哲思的作品既是太合麦田倡导良心音乐的实证又是“新红白蓝”系列清新隽永的醒目特色。唱作俱佳的王凡瑞包揽了专辑内所有作品的词曲唱，编曲和制作人则由曾先后担任过', NULL, '2010-01-02', '太合麦田', '/covers/257-王梵瑞-青春.jpg', '41:30', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2006, 'Folk,Pop', NULL, 247, 39, 18, NULL, NULL, NULL, NULL, NULL, 'b834a9fd-263b-44ab-a6b4-6c407ee7d2c5', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (258, '时光谣', '王梵瑞', '中国', '大陆', 'Folk,Pop', NULL, '时光谣——这是一张充满时间感及个人蜕变的唱片。相距第二张专辑整整四年的时光，四年后的王梵瑞、用了新名字的王梵瑞！你还认识这个歌手么？音乐及造型的完全突破，雕刻这避无可避的时光歌谣。', NULL, '2015-07-27', '众水之音', '/covers/258-王梵瑞-时光谣.jpg', '4:36', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2013, 'Folk,Pop', NULL, 247, 39, 18, NULL, NULL, NULL, NULL, NULL, '3f74a485-438c-4cc1-ab8a-c424347a383b', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (259, '等候', '王梵瑞', '中国', '大陆', 'Folk,Pop', NULL, '王凡瑞全新创作大碟《等候 王凡瑞》 震撼心灵的音乐情感巨作 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (260, '最美的时光', '满江', '中国', '大陆', 'Mandopop', NULL, '满江一直以来都不是一个多产的歌手，从早期唱别人的歌到后来坚持走创作路线并担任制作，基本上都保持着两年一张专辑的速度，因为这样他认为更能保证唱片质量。自上一张初显乐队化的《百万富翁》之后又是两年的时间，这一次的新唱片乐队风格更加鲜明，特别是歌词和编曲部分，作为制作人的满江要求比上一张更加严格，令合作多年的内地著名词作者吴向飞此次叫苦不迭，称从没写得如此辛苦，简直快到崩溃；而编曲被逼着修改5、6次音乐更是常事。严于律人的满江自然更严于律己，甚至勇于挑战自我，大胆尝试新唱法，一改了十多年的录音习惯，并取得了意想不到的效果，也是他此次新专辑一个不小的收获。', 0, '2015-06-27', '上海声像', '/covers/260-满江-最美的时光.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2010, 'Pop', '满江', 240, 2, 2, NULL, NULL, NULL, NULL, NULL, '696a2413-1738-4658-bdc7-c7df475706a7', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (261, 'Murmur', 'R.E.M.', '美国', '佐治亚州', 'Jangle Pop, Alternative Rock', NULL, 'Murmur is the debut studio album by American alternative rock band R.E.M., released on April 12, 1983, by I.R.S. Records. The album was recorded in the winter of 1983 at Reflection Sound Studios in Charlotte, North Carolina, with musicians Don Dixon and Mitch Easter serving as producers. Murmur received critical acclaim upon release for its unconventional sound, defined by lead singer Michael Stipe''s cryptic lyrics, guitarist Peter Buck''s jangly playing, and Mike Mills'' melodic basslines. In 2003, the album was ranked number 197 in Rolling Stone magazine''s list of the "500 Greatest Albums of All Time". It retained the position in the 2012 list and was raised to number 165 in the 2020 revision.', 0, '2011-11-08', 'I.R.S. Records', '/covers/261-R.E.M.-Murmur.jpg', '44:12', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1983, 'Rock', 'Mitch Easter,Don Dixon', 121, 139, 1, NULL, NULL, NULL, 10, 'https://pitchfork.com/reviews/albums/12464-murmur-deluxe-edition/', '10f4f4ca-d983-4dda-9095-b89d58882953', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (262, '蓝色的脸', '大波浪', '中国', '大陆', 'New Wave', NULL, '蓝色，是一种颜色，它是红绿蓝光的三原色中的一员，在这三种原色中它的波长最短。蓝色是永恒的象征，它是最冷的色彩，代表着大海和天空，给人一种广阔无垠、神秘莫测又永恒不变的感受；然而蓝色的脸，是忧郁的，孤独的，冰冷的，病态的，扭曲的，充满了离奇感和不真实感。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (263, 'Illmatic', 'Nas', '美国', '纽约', 'East Coast Hip Hop, Boom Bap, Hardcore Hip Hop', NULL, 'Nas: Time Is Illmatic is a 2014 documentary film directed by One9 and produced by One9, Erik Parker and Anthony Saleh. The film recounts the circumstances leading up to Nas'' 1994 debut album Illmatic. Released on the 20th anniversary of Illmatic, the film includes interviews with Nas, his brother and father, and figures from the East Coast hip hop scene. Nas: Time Is Illmatic premiered during the opening night of the 2014 Tribeca Film Festival, on April 16, 2014. The project received a grant from Tribeca All Access and additional funding from the Ford Foundation.', 0, '2025-01-08', 'Columbia Records', '/covers/263-Nas-Illmatic.jpg', '39:41', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1994, 'Hip Hop', NULL, 101, 141, 27, NULL, NULL, NULL, 10, 'https://pitchfork.com/reviews/albums/17497-illmatic/', '2e7c03a2-2ef9-4563-bb6d-ebc65eed77e4', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (266, '祝你幸福', '马飞', '中国', '大陆', 'Folk', NULL, '2024年，郊眠寺，马飞时隔十年的第二张全新录音室专辑。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (267, '珍珠刑', '魏如萱', '中国', '台湾', 'Mandopop, Art Pop', NULL, '暂且挖开这张口 凌驾于心的占有
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (268, '末路狂花', '魏如萱', '中国', '台湾', 'Indie Pop, Mandopop, Art Pop, Indie Folk', NULL, '我 的 人 生 不 能 就 这 样 被 打 发 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (269, 'Hunky Dory', 'David Bowie', '英国', '伦敦', 'Pop Rock, Glam Rock, Art Rock', NULL, 'Hunky Dory is the fourth studio album by the English musician David Bowie, released in the United Kingdom on 17 December 1971 through RCA Records. Following a break from touring and recording, Bowie settled down to write new songs, composing on piano rather than guitar as in earlier works. Bowie assembled Mick Ronson (guitar), Trevor Bolder (bass) and Mick Woodmansey (drums), and recorded the album in mid-1971 at Trident Studios in London. Rick Wakeman contributed piano shortly before joining Yes. Bowie co-produced the album with Ken Scott, who had engineered Bowie''s previous two records.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (270, 'Bright Future', 'Adrianne Lenker', '美国', '印第安纳波利斯', 'Singer-Songwriter, Contemporary Folk', NULL, 'Bright Future is the sixth solo studio album by Adrianne Lenker. It was released on March 22, 2024, through 4AD. The album received widespread acclaim and was nominated for Best Folk Album at the 67th Annual Grammy Awards.', 0, '2024-03-22', '4AD', '/covers/270-Adrianne Lenker-Bright Future.jpg', '43:37', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2024, 'Folk', 'Philip Weinrobe', 4, 145, 3, NULL, NULL, NULL, 8.4, 'https://pitchfork.com/reviews/albums/adrianne-lenker-bright-future/', '0d5f067b-ca62-4a7c-950a-0af030c53df3', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (271, 'Heartwork', 'Carcass', '英国', '利物浦', 'Melodic Death Metal', NULL, 'Heartwork is the fourth studio album by English extreme metal band Carcass. The album was released in the UK on 18 October 1993 by Earache Records, and in the United States on 11 January 1994 by Columbia Records, making it the band''s only major label release. Heartwork has been described as the band''s "breakthrough" and "mid-period masterpiece", as well as a landmark album in melodic death metal. The album was recorded at Parr Street Studios, Liverpool from 18 May – 21 June 1993.', 0, '2025-03-14', 'Earache', '/covers/271-Carcass-Heartwork.jpg', '41:50', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1993, 'Metal', 'Colin Richardson', 32, 146, 16, NULL, NULL, NULL, NULL, NULL, '0b7fa0b4-0c1b-4621-89ed-ef849485341b', 'active');
