INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (280, '爱情多恼河', '熊天平', '中国', '台湾', 'Mandopop', NULL, '《爱情多恼河》是熊天平于1997年发行的首张录音室专辑，共收录12首歌曲，由袁惟仁、刘天健、徐德昌、黄国伦担任制作人。1997年，专辑同名曲《爱情多恼河》获得第四届全球华语音乐榜中榜“中文Top20榜中榜歌曲”奖。', 0, '2014-03-12', '上华', '/covers/280-熊天平-爱情多恼河.jpg', '54:36', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1997, 'Pop', NULL, 241, 2, 2, NULL, NULL, NULL, NULL, NULL, '7d3c07f3-cb17-49b3-9772-930091780a0f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (281, '影之传说', '陈楚生', '中国', '大陆', 'Mandopop', NULL, '楚生创作的新影视专辑，用最真诚的声音唱出最纯粹的音乐感染力.楚生创作的新影视专辑，用最真诚的声音唱出最纯粹的音乐感染力楚生创作的新影视专辑
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (282, '十年全纪录', '熊天平', '中国', '台湾', 'Mandopop', NULL, '2006年，正合世纪，2006年，熊天平携带着定位于新古典、新气质的《十年全纪录》重出江湖。新专辑囊括了他全新演绎的6首经典作品，以及反映他五年心路历程的7首全新作品。这张《十年全纪', 0, '2014-05-11', '正合世纪', '/covers/282-熊天平-十年全纪录.jpg', '60:05', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2006, 'Pop', NULL, 241, 2, 2, NULL, NULL, NULL, NULL, NULL, '2c4f4cd5-bc17-4bdb-80a2-ac849db32c86', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (283, '原谅我就是这样的女生', '戴佩妮', '中国', '台湾', 'Mandopop', NULL, '暌违两年没发片的金曲才女戴佩妮，自上一张唱片《iPenny》后作多元化发展，推出新书《Oh my day》，以及多首数位单曲，又跨足担任导演、摄影师和执导MV。2009年，Penny集结多首单曲和新作并推出第八张创作专辑《原谅我就是这样的女生》。最新主打歌“两难”采用了有别以往的唱腔，充满了中国曲风的特色，且混合了西洋编曲，Penny 以细腻捕捉了爱情故事中的矛盾又惆怅的心情。
