INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (290, '甜蜜生活', '魏如萱', '中国', '台湾', 'Indie Pop', NULL, '为了拯救我的眼睛，我不得不中午冒上来更新，可能做得会比较粗。“自然卷”很多人都不会陌生，卷卷的女声个人感觉太太小女生，嫩撮撮的！不那么对味，但她的受欢迎程度是有目共暏的。单飞后这张处女作《甜蜜生活》也是结合了西班牙、德国、日本、中国等多方优秀音乐人跨国合作，带给大家一种与众不同、清新沁人的幸福味道！ 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (291, '冬霾', '葬尸湖', '中国', '大陆', 'Atmospheric Black Metal, DSBM', NULL, '2012年，这张小专辑的2首曲目是乐队成员在创作第一张专辑《奕秋》时产生意见分歧下的作品，故不收录在正式专辑中。', 0, '2025-04-12', '瘟疫唱片', '/covers/291-葬尸湖-冬霾.jpg', '15:12', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2012, 'Metal', NULL, 264, 152, 16, NULL, NULL, NULL, NULL, NULL, '1b867e9b-b953-4a33-8c44-9ee2f7bda2b0', 'active');
