INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (296, '闪亮的日子', '罗大佑', '中国', '台湾', 'Mandopop,Campus Folk', NULL, '抛开屋外喧腾吵嚷难辩的道理，忘记满天飞舞不解的谎言，安静聆听罗大佑的音乐，把美一首歌和生命里的一段故事放在一起，那就是你的回 忆，是你生命得的乐曲。歌曲包括: 爱的箴言，痴痴的等，光阴的故事....等等。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (297, '听上去不错', '郑钧', '中国', '大陆', 'Pop Rock', NULL, '现在的人都急于表达，不愿用心聆听。然而，拥有一颗能够聆听的心也许比听什么说什么更宝贵，因为一切的美好感受都是来自那里，那颗不急不慌放松自在柔软喜悦的心', 0, '2019-07-07', '地球娱乐', '/covers/297-郑钧-听上去不错.jpg', '41:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2019, 'Rock', NULL, 287, 1, 1, NULL, NULL, NULL, NULL, NULL, 'def4dcbc-44dc-48e5-8a00-2c9ea9fea918', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (298, '水木年华3（新歌+精选）', '水木年华', '中国', '大陆', 'Mandopop', NULL, '2003年，瀚星艺能，随着卢庚戌个人随笔集的问世，“水木年华”的第三张专辑进入了大家的视野。这是一张“新歌+精选”的专辑。“水木年华”在失去了优雅的李健后，增添了两名充满动感与活力的', 0, '2025-05-02', '水木有你', '/covers/298-水木年华-水木年华3（新歌+精选）.jpg', '46:56', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2003, 'Pop', NULL, 232, 2, 2, NULL, NULL, NULL, NULL, NULL, 'ef97eb29-ed51-4b06-9f91-68808c2b2946', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (299, '70.80', '水木年华', '中国', '大陆', 'Mandopop', NULL, '音乐最具震撼力的组合和声最趋二完美的搭配，一张70年代80年代生人不容错过的好专辑。
