INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (301, '梦回唐朝', '唐朝', '中国', '大陆', 'Heavy Metal', NULL, '1992年，滚石唱片，唐朝乐队成立于1988年，在四年艰困的成长过程中，有无数血泪交织的故事。你现在所听到的作品，是他们的第一张专辑，也是第一次在录音室内作业的成果。对于他们的成绩，', 0, '2014-08-18', '魔岩唱片', '/covers/301-唐朝-梦回唐朝.jpg', '60:14', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1992, 'Metal', NULL, 185, 153, 16, NULL, NULL, NULL, NULL, NULL, '138fff0b-86c6-449f-baee-7a79df3d173d', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (302, '黑豹', '黑豹', '中国', '大陆', 'Glam Metal, Hard Rock', NULL, '1992年，滚石唱片，《无地自容》时候的黑豹无疑是优秀的，是中国摇滚界重金属和硬摇滚的代表，《无地自容》取得了难以置信的轰动，以至于有人群的地方肯定就有人在哼唱黑豹的摇滚。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (303, '亲爱的...我还不知道', '张悬', '中国', '台湾', 'Singer-Songwriter, Acoustic Rock, Folk Pop', NULL, '2007年，索尼音乐，五年前的作品「My Life Will…」发行后深受好评「宝贝」温暖了许多人的心金曲奖最大遗珠之憾　张悬说：评审是要我更努力…
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (304, '昼夜本色第二季', '梁博', '中国', '大陆', 'Pop Rock, Mandopop, Singer-Songwriter', NULL, '《昼夜本色》是由歌手梁博发起并制作，围绕着声音探索，环境变化，当下状态，随性纪录的一档个人音乐现场节目。在《昼夜本色》里“丑也是美” 所以节目风格经常在记录精彩片段的同时也会保留一些现场的瑕疵和插曲，以及一些随性的时刻。第一季是钢琴即兴弹唱，无修音，利用现场自然混响尝试混音。 第二季继续探索，无修音，无混音，无母带。当天的录音直接导出就是大家听到的这样。无论怎样，形式只是满足当下内心的尝试和玩法，忠于内心，真实的传递音乐和感受就是《昼夜本色》 的精神。', 0, '2025-04-25', '森林文化', '/covers/304-梁博-昼夜本色第二季.jpg', '39:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2023, 'Rock,Pop', NULL, 230, 121, 17, NULL, NULL, NULL, NULL, NULL, 'a087ff08-d350-4b30-9a67-ccd597f4f8e4', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (305, '我不是随便的花朵', '姜昕', '中国', '大陆', 'Folk,Rock', NULL, '从春到……秋，我们终于再次迎来了她生命里花开不败的第四个春天 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (307, '泡泡', '魏如萱', '中国', '台湾', 'Indie Pop', NULL, '魏如萱勇敢用音乐表态 陈建骐提供自由的创作氧气  
