INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (309, 'Easy', '彭坦', '中国', '大陆', 'Mandopop', NULL, '2010年，这是一张有趣的不插电专辑，首次担当出品人以及制作人，得以亲历一张唱片从无到有所要付出的繁杂工作，也是乐在其中的体验。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (310, '唱片', '王啸坤', '中国', '大陆', 'Mandopop', NULL, '1888年，世界上第一张碟形唱片由伯利纳发明，在美国诞生。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (311, '咒语', '野孩子', '中国', '大陆', 'Contemporary Folk', NULL, '他们不追逐流行时尚，因为他们知道真正的音乐从不会过时。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (312, '阿密特2', '张惠妹', '中国', '台湾', 'Pop Rock,Mandopop', NULL, '你 看得见自己的灵魂吗？
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (313, '...And Justice for All', 'Metallica', '美国', '洛杉矶', 'Thrash Metal', NULL, '...And Justice for All is the fourth studio album by American heavy metal band Metallica, released on September 7, 1988, by Elektra Records. It was Metallica''s first full-length studio album to feature bassist Jason Newsted following the death of Cliff Burton in 1986. Burton received posthumous co-writing credit on "To Live Is to Die" as Newsted followed bass lines Burton had recorded before his death.', 0, '2025-03-18', 'Elektra', '/covers/313-Metallica-...And Justice for All.jpg', '65:10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1988, 'Metal', 'Metallica,Flemming Rasmussen', 93, 54, 16, NULL, NULL, NULL, 9.3, 'https://pitchfork.com/reviews/albums/metallica-and-justice-for-all/', 'c5c80303-bf31-456c-9f18-cd913cf8fdd4', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (314, 'The New Sound', 'Geordie Greep', '英国', '伦敦', '	Jazz-Rock, Progressive Rock, Art Rock', NULL, 'Sound is a phenomenon in which pressure disturbances propagate through an elastic material medium. In the context of physics, it is characterised as a mechanical wave of pressure or related quantities (e.g. displacement), whereas in physiological-psychological contexts it refers to the reception of such waves and their perception by the brain. Though sensitivity to sound varies among all organisms, the human ear is sensitive to frequencies ranging from 20 Hz to 20 kHz. Examples of the significance and application of sound include music, medical imaging techniques, oral language and parts of science.', 0, '2024-08-10', 'Rough Trade', '/covers/314-Geordie Greep-The New Sound.jpg', '62:55', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2024, 'Rock', 'Seth "Shank" Evans', 61, NULL, 1, NULL, NULL, NULL, 7.2, 'https://pitchfork.com/reviews/albums/geordie-greep-the-new-sound/', '1a324be6-d8f7-4bce-b830-df5cf4d85bdb', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (315, 'Under Cover', 'Ozzy Osbourne', '英国', '西米德兰兹郡', 'Hard Rock, Heavy Metal', NULL, 'Under Cover is the ninth studio album by the English heavy metal singer Ozzy Osbourne. The album consists entirely of cover songs, with an emphasis on rock music from the 1960s and 1970s. This is Osbourne''s first and only album to feature cover songs from various artists, although in 1982, Osbourne released the live album Speak of the Devil featuring renditions of songs from his time with Black Sabbath. All but four songs were originally released in the box set Prince of Darkness, released earlier the same year. The additional songs are "Rocky Mountain Way", "Sunshine of Your Love", "Woman" and "Go Now". Whilst he cites The Beatles as his favourite band, his favourite song of all time is Procol Harum''s "A Whiter Shade of Pale". He had wished to cover this song but was advised against it since it had recently been covered by a "close musical associate"  (then-former guitarist Zakk Wylde covered the song with his band Black Label Society on their 2004 album Hangover Music Vol. VI).
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (316, 'The Queen Is Dead', 'The Smiths', '英国', '曼彻斯特', 'Jangle Pop, Indie Pop', NULL, 'The Queen Is Dead is the third studio album by the English rock band the Smiths, released on 16 June 1986 by Rough Trade Records. Following the release of their second album Meat Is Murder, the Smiths retreated to Greater Manchester to begin work on new material, with Johnny Marr and Morrissey writing extensively at Marr''s home in Bowdon as the band sought to escape the pressures of London and their label Rough Trade. The album was produced by Morrissey and Marr, with engineering by Stephen Street; its music blends indie rock and post-punk. Recording for the album took place between July 1985 and December of that year, with sessions held at RAK Studios in London, Jacobs Studios in Farnham and Drone Studios in Manchester.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (317, 'Metallica', 'Metallica', '美国', '洛杉矶', 'Heavy Metal', NULL, 'Metallica (commonly known as The Black Album) is the fifth studio album by American heavy metal band Metallica. It was released on August 12, 1991, by Elektra Records. Recording sessions took place at One on One Recording Studios in Los Angeles over an eight-month span that frequently found Metallica at odds with their new producer Bob Rock. The album marked a change in the band''s music from the thrash metal style of their previous four albums to a slower, heavier, and more refined sound.
