INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (319, '好好享受人类的莫名其妙', '秦凡淇', '中国', '大陆', 'Mandopop', NULL, '秦凡淇首张创作专辑「好好享受人类的莫名其妙」
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (320, 'Converging Ages', 'Inanna', '智利', '圣地亚哥', 'Progressive Metal, Melodic Death Metal', NULL, '国际，2011', 0, '2025-04-11', 'Corvus', '/covers/320-Inanna-Converging Ages.jpg', '59:08', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2008, 'Metal', 'Inanna', 68, 162, 16, NULL, NULL, NULL, NULL, NULL, '67b99abb-d99d-4767-bc58-9d3243291b95', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (321, 'Crimson', 'Edge of Sanity', '瑞典', NULL, 'Melodic Death Metal, Progressive Metal', NULL, 'Crimson is the fifth full-length studio album by Swedish death metal band Edge of Sanity, which is their first concept album and was released in 1996 by Black Mark Production. It features a single 40-minute track, telling a story in the distant future, when human civilization is about to end.', 0, '2025-04-11', 'Black Mark Production', '/covers/321-Edge of Sanity-Crimson.jpg', '40:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1996, 'Metal', NULL, 54, 163, 16, 3.91, 0, '', NULL, NULL, '24336ee0-5d57-46e2-84d5-a5be15d6bc01', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (322, 'Dead as Dreams', 'Weakling', '美国', '洛杉矶', 'Atmospheric Black Metal, Black Metal', NULL, 'Dead as Dreams is the only studio album by American black metal band Weakling. It was recorded in 1998 and released in 2000, through the tUMULt record label, while the band itself ceased activity in 1999. The title of the album comes from a line in the movie Legend, while the art featured on the cover is a print by Spanish artist Francisco Goya titled Buen Viaje from the set Los caprichos.', 0, '2025-04-17', 'tUMULt', '/covers/322-Weakling-Dead as Dreams.jpg', '76:09', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2000, 'Metal', NULL, 155, 164, 16, NULL, NULL, NULL, NULL, NULL, '86052e0c-f060-44bf-9278-ce869b85e5bb', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (323, 'Twin Fantasy', 'Car Seat Headrest', '美国', '弗吉尼亚州', 'Slacker Rock', NULL, 'Twin Fantasy, later re-titled Twin Fantasy (Mirror to Mirror), is the sixth solo studio album by American indie rock musician Will Toledo, under his alias Car Seat Headrest. Since its release on November 2, 2011, the album has amassed an online cult following,  with the internet forums 4chan and Reddit playing major roles in the album''s initial success. A re-recording of the album was released via Matador Records on February 16, 2018.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (324, '1184', '	Windir', '挪威', NULL, 'Melodic Black Metal', NULL, '1184 is the third studio album by Windir, released in 2001. Valfar composed this album with the band Ulcus. Departing from the sound for which Windir is normally known, it nevertheless kept its folk elements, albeit with inspiration from electronic music. The art used in the album cover is a painting by the Norwegian artist Johan Christian Dahl called "Winter at the Sognefjord".', 0, '2025-04-19', 'Head Not Found', '/covers/324-Windir-1184.jpg', '51:37', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2001, 'Metal', 'Valfar', 1, 98, 16, NULL, NULL, NULL, NULL, NULL, '183b3674-208a-4717-87d3-745123af7cc6', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (325, 'The Cure', 'The Cure', '英国', '西萨塞克斯', 'Alternative Rock', NULL, 'The Cure are an English rock band formed in Crawley in 1976 by Robert Smith (vocals, guitar) and Lol Tolhurst (drums). As of 2026, the band''s line-up comprises Smith, Simon Gallup (bass), Roger O''Donnell (keyboards), Jason Cooper (drums) and Reeves Gabrels (guitar). Smith has remained the only constant member throughout numerous line-up changes since the band''s formation.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (326, '舞娘', '蔡依林', '中国', '台湾', 'Mandopop,Dance-Pop', NULL, '挥舞彩带展现舞娘身段妩媚肢体的 Jolin
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (327, '夜官巡场', '装咖人', '中国', '台湾', 'Alternative Rock', NULL, '装咖人2021年专辑《夜官巡场》，台湾另类摇滚。台语摇滚的在地叙事，夜色中的官将仪式与民间信仰。', 0, '2025-07-01', '风潮音乐', '/covers/327-装咖人-夜官巡场.jpg', '49:51', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2021, 'Rock', NULL, 267, 5, 1, NULL, NULL, NULL, NULL, NULL, 'ae64bfea-48a1-4ba5-9275-4fbb947fff19', 'active');
