INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (329, '荒腔走板 选段', '大忘杠', '中国', '大陆', 'Avant-Folk', NULL, '2015年，来自中国的有传统意识并能引发幻象的先锋,独立的音响艺术叙事，充满力量，出神入化，完全当代 !--德国唱片评论家奖
