INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (332, '极夜', '霜冻前夜', '中国', '大陆', 'Melodic Death Metal, Power Metal', NULL, '2009年，号角唱片，中国旋律死亡金属娇楚“霜冻前夜”的最新专辑《极夜》的出版发行，以此昭示着这支乐队多年历练后的尘埃落定。一如既往的欧式旋律死亡特性；铿锵的激流金属节奏，一如既往的', 0, '2025-08-03', 'Mort Productions', '/covers/332-霜冻前夜-极夜.jpg', '36:24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2009, 'Metal', NULL, 301, 51, 16, NULL, NULL, NULL, NULL, NULL, '40a6db13-0751-4bbb-a213-07079a6c2f06', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (333, '原乡', '罗大佑', '中国', '台湾', 'Synthpop', NULL, '《原乡》是罗大佑于1991年9月26日发行的专辑，共收录12首作品，融合电子合成、民谣与华语流行元素，展现其对故乡、社会与人文的深刻关怀。专辑中与周华健、李宗盛、赵传等人合作，呈现九十年代台湾音乐的多元面貌。', 0, '2025-08-18', '大右音乐事业有限公司', '/covers/333-罗大佑-原乡.jpg', '37:56', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1991, 'Pop', NULL, 255, 169, 2, NULL, NULL, NULL, NULL, NULL, 'ec3ac7bc-8500-3b0f-a6a4-fbb868c5ea3d', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (334, '新台币', 'Baboo', '中国', '台湾', 'Chamber Folk, Art Pop', NULL, '国际，2011', 0, '2025-07-20', '滚石唱片', '/covers/334-Baboo-新台币.jpg', '42:24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1992, 'Folk,Pop', NULL, 18, 170, 18, NULL, NULL, NULL, NULL, NULL, '78015f5e-2f43-467b-ac0d-fe22b8d7d15b', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (335, '演义', '唐朝', '中国', '大陆', 'Heavy Metal, Progressive Metal, Folk Metal', NULL, '唐朝乐队1999年发行的第二张录音室专辑，融合重金属、前卫金属与中国传统元素，展现宏大叙事与文化意象。', 0, '2025-07-27', '京文唱片', '/covers/335-唐朝-演义.jpg', '62:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1999, 'Metal,Rock', NULL, 185, 171, 20, NULL, NULL, NULL, NULL, NULL, '01284f00-b88b-40ba-9d8c-7de84fcdccd5', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (336, 'Carsick Cars', 'Carsick Cars', '中国', '大陆', 'Noise Rock, Indie Rock, Post-Punk, Noise Pop, Jangle Pop', NULL, 'Carsick Cars 的首张专辑融合了中国地下摇滚与 Sonic Youth 式的噪音美学，是北京独立音乐场景的重要标志之一。', 0, '2025-07-28', '兵马司唱片', '/covers/336-Carsick Cars-Carsick Cars.jpg', '53:59', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2007, 'Rock', 'Michael Pettis', 34, 172, 1, NULL, NULL, NULL, NULL, NULL, '5e8013e7-7329-4a8f-a5bd-ccaaad156e32', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (337, '神经', '达明一派', '中国', '香港', 'Art Pop, Synthpop, Ambient Pop, Sophisti-Pop, Indie Pop', '3.67', '《神经》是达明一派于1990年发行的专辑，融合电子流行、氛围流行与爵士元素，以粤语呈现都市感与政治讽刺，被视为香港艺术流行的代表作之一。', 0, '2025-07-29', '宝丽金唱片', '/covers/337-达明一派-神经.jpg', '2:58', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1990, 'Pop,Electronic', NULL, 281, 173, 39, NULL, NULL, NULL, NULL, NULL, '5a5f75ff-0a46-4c90-91a0-ba2ca7f969c9', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (338, '你来自何方', '许景淳', '中国', '台湾', 'Baroque Pop, Sophisti-Pop, Adult Contemporary, Chamber Pop', '3.5', '《你来自何方》是许景淳于1992年发行的概念专辑，融合古典流行与室内编制，展现女性内心的孤独与诗意，被誉为华语流行音乐中极具美学深度的作品。', 0, '2025-07-30', '滚石唱片', '/covers/338-许景淳-你来自何方.jpg', '47:22', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1992, 'Pop', '', 272, 174, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (339, '茫茫集', '噬湖', '中国', '大陆', 'Avant-Garde Metal, Doom Metal', NULL, '《茫茫集》红楼组曲聚焦古典文学巨著《红楼梦》，以其最具代表性的人物和故事创作成九支曲目，将书中四大家族的兴衰存亡史汇成一部可悲、可惜、可叹的千古绝唱。', 0, '2025-08-21', 'Infected Blood Records', '/covers/339-噬湖-茫茫集.jpg', '43:28', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2023, 'Metal', NULL, 187, 175, 16, NULL, NULL, NULL, NULL, NULL, '7e81a0d6-bf26-4835-b9a1-c696681aca8b', 'active');
