INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (341, '凝华', '霜冻前夜', '中国', '大陆', 'Symphonic Metal, Melodic Death Metal', NULL, '2019年，十五周年纪念专辑《凝华》于2019霜冻前夜首次大规模全国巡演之际发行。在缅怀15年音乐历程的同时，也昭示着这支中国式旋律死亡金属乐队开始了全新音乐道路的启程。这', 0, '2025-08-21', '墓志铭唱片', '/covers/341-霜冻前夜-凝华.jpg', '28:39', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2019, 'Metal', NULL, 301, 177, 16, NULL, NULL, NULL, NULL, NULL, '3e3a0e77-b57a-43ab-b86d-60b5ada12232', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (342, 'Lost & Found 去寻找', '牛奶咖啡', '中国', '大陆', 'Mandopop, Acoustic Pop', NULL, '2011年，一年之后，再次看见牛奶咖啡，他们对生活的理解已经有了新的方向。延续了上一张《给你点颜色》中“改变，让生活更美好”的积极意义，“歌唱美好生活”的内地原创音乐组合“', 0, '2025-08-21', '华谊音乐', '/covers/342-牛奶咖啡-Lost & Found 去寻找.jpg', '18:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2011, 'Pop', NULL, 242, 178, 2, NULL, NULL, NULL, NULL, NULL, '083eca84-2b81-423a-b3cd-6244b9fcf7e0', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (343, '八方来财', '揽佬SKAI ISYOURGOD', '中国', '大陆', 'Trap, Memphis Rap', '3.57', '2024年，秀动发行，《八方来财》是揽佬第二张“揽式孟菲斯”音乐专辑，依旧很摇又有点不摇。
