INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (348, '春龙交响夜2024', '罗大佑', '中国', '台湾', 'Live Orchestral Pop, Art Pop', '5.0', '§《春龙交响夜2024》现场录音专辑§
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (349, '无能的力量', '崔健', '中国', '大陆', 'Rap Rock, Art Rock, Alternative Rock, Folk Rock', '3.78', '在这个世纪之末，和下一个世纪就要开始的时代，我向大家推荐一个真正的音乐家和斗士--崔健带来的令人为之一震的专辑--《无能的力量》。这张专辑是对崔健本人的演唱生涯，也是对中国社会在一个世纪末的总结。 我不想把崔健的东西拔得很高，但这是不诤的事实。我不能不说崔健仍然年轻，而且是年轻人中的年轻人。有很多人在年轻的时侯就已经老了。这对于他们而言是个悲剧，无论你已意识到或毫无知觉。 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (350, '给你一点颜色', '崔健', '中国', '大陆', 'Experimental Hip Hop, Art Rock, Industrial Hip Hop, Chinese Folk Music, Rap Rock', '3.5', '从《新长征路上的摇滚》、《解决》、《红旗下的蛋》、《无能的力量》到《给你一点颜色》，崔健始终强调对个性的张扬以及独立、自由创作的重要性。同时，这张专辑和以往几张最大的不同之处是风格更多元化，更独立，更整体。这张专辑有三种颜色，但用一条线穿起来，有流行的、摇滚的，电子的和HIP-HOP音乐等等，极大丰富了专辑的可能性。 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (351, '堕落天使', '郑智化', '中国', '台湾', 'Mandopop, Pop Rock', '3.75', '郑智化1990年发行的代表作之一，融合流行摇滚与抒情元素，展现其对青春、信仰与社会的深刻反思。专辑风格鲜明，歌词富有哲理性与批判性，是台湾流行音乐黄金年代的重要作品。', 0, '2025-08-21', '可登有声', '/covers/351-郑智化-堕落天使.jpg', '41:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1990, 'Pop', NULL, 286, 186, 2, NULL, NULL, NULL, NULL, NULL, 'a0cf925c-c7b8-4ce9-83dd-e0f87891d11f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (353, 'You Can Listen, You Can Talk', 'Carsick Cars', '中国', '大陆', 'Indie Rock, Noise Rock, Neo-Psychedelia, Shoegaze, Jangle Pop', '3.13', 'Carsick Cars于2009年发行的第二张录音室专辑，延续其噪音摇滚与迷幻流行的风格，整体音色更为成熟与细腻。专辑中融合中英文歌词，展现出中国独立音乐在国际语境中的探索与表达。', 0, '2025-08-21', '兵马司唱片', '/covers/353-Carsick Cars-You Can Listen, You Can Talk.jpg', '54:11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2009, 'Rock', NULL, 34, 187, 1, NULL, NULL, NULL, NULL, NULL, '86e4ec9e-85b6-4297-b1b3-ae3d1522a2c1', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (354, '将爱', '王菲', '中国', '大陆', 'Mandopop, Art Pop', '3.72', '风风火火 轰轰烈烈 All-In！史上首次最高荣耀金曲奖7大奖项8项入围：最佳国语女演唱人/最佳专辑/最佳制作人/最佳作曲/最佳作词/最佳编曲/最佳MV
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (355, '幻听', '窦唯', '中国', '大陆', 'Dream Pop', '3.62', '这实际上是一个以窦唯为主的乐队作品。专辑名称《幻听》,乐队名称“译”(E)。乐队成员包括窦唯(主唱、吉他、键盘),陈劲(贝司),讴歌(主音吉他),晓帆(鼓、打击乐)。都是很熟悉的名字,对吧。可是音乐上的感觉就不太熟悉了。虽说窦唯这回玩的是Band Sound,但是绝对不同于早期那种比较明朗、亲和力较强的风格,而是显得有些晦涩。这种晦涩还不光表现在音乐风格和乐队名称上,看看专辑中的歌名:“幻听”、“旺天下”、“丰收获”、“觉是”、“荡空山”等等。一片香烟缭绕,天地清净,酒肉穿肠的玄虚氛围。', 0, '2014-01-27', '滚石唱片', '/covers/355-窦唯-幻听.jpg', '42:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2001, 'Rock', NULL, 253, 109, 1, NULL, NULL, NULL, NULL, NULL, '3b3d6226-9148-4acd-a647-9112480c17d5', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (356, '艳阳天', '窦唯', '中国', '大陆', 'Dream Pop, New Wave, Chinese Folk Music', '3.52', '窦唯95年最新专辑《艳阳天》
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (357, '北之国 IV', '水树', '中国', '大陆', 'BlackGaze', NULL, '2021年', 0, '2025-08-27', '风马乐音（北京）文化传媒有限公司', '/covers/357-水树-北之国 IV.jpg', '1:01', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2021, 'Metal', NULL, 233, 189, 16, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (358, '西湖波底月', '深山', '中国', '大陆', 'Post-Metal, Atmospheric Black Metal, Post-Rock, Folk Metal', '3.08', '2022年，北宋崇宁四年（公元1105年），宋徽宗命蔡京执笔《元祐党籍碑》，将司马光、文彦博、苏辙、苏轼、秦观、黄庭坚、张耒、晁补之、程颐、李格非等反对朝廷乱政的文人、官员', 0, '2025-08-27', '瘟疫唱片', '/covers/358-深山-西湖波底月.jpg', '21:29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2022, 'Metal', NULL, 239, 190, 16, NULL, NULL, NULL, NULL, NULL, '35736c2b-891a-4836-8455-68f429792f8f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (360, '只爱陌生人', '王菲', '中国', '大陆', 'Pop, Art Pop, Pop Rock, Trip Hop, Dream Pop, Alternative Rock, Contemporary Folk', '3.72', '《只爱陌生人》是香港歌手王菲的第16张大碟、第7张国语大碟，在百代唱片的第三张大碟，于1999年9月10日发行。一共12首歌曲：10首为国语，2首粤语歌是将碟中2首国语歌重新填词为粤语，照顾香港市场；同名曲为翻唱张亚东的作品。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (361, '唱游', '王菲', '中国', '大陆', 'Dream Pop, Pop, Indie Pop, Trip Hop, Folk Pop, Ethereal Wave, Ambient Pop, Art Pop', '3.65', '王菲《唱游》是华语流行音乐市场第一张采取“HDCD”的编码录音专辑。目前全世界只有古典唱片或少数讲究真实、立体、层次极饱满的发烧片，才是以“HDCD”方式编译录制完成。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (363, 'Around the Fur', 'Deftones', '美国', '加利福尼亚', 'Nu Metal, Alternative Metal, Post-Hardcore', NULL, 'Around the Fur is the second studio album by the American alternative metal band Deftones, released on October 28, 1997, through Maverick Records. The songs "My Own Summer " and "Be Quiet and Drive " were released as singles with accompanying music videos. The album was certified Gold by the RIAA in 1999, and then Platinum in 2011.', 0, '2025-08-25', 'Maverick唱片', '/covers/363-Deftones-Around the Fur.jpg', '74:01', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1997, 'Metal', 'Terry Date, Deftones', 48, 193, 16, NULL, NULL, NULL, NULL, NULL, '2148735a-d5d1-437b-b184-643bdf20656f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (364, '无法逃脱', '指南针', '中国', '北京', 'Pop Rock', '2.66', '指南针乐队成立于1990年，乐队前身为“黑马乐队”。1991年从成都至北京发展，后易名为“指南针”乐队，寓意乐队对音乐永恒的热爱以及对音乐理想的不懈追求。他们是一个团结、融洽而可爱的集体。聪颖顽皮而极具天赋的主唱罗琦，技术全面的吉他手周迪（乐队的灵魂），音乐修养深厚的键盘手郭亮，浑身都是节奏感的鼓手郑朝晖，性格文静而诙谐的贝斯手岳浩昆和萨克斯手苑丁组成了最早的指南针乐队，是当时摇滚乐坛唯一一个非北京籍摇滚乐队（除罗琦外其他成员都是四川人）。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (365, '飞狗', '崔健', '中国', '大陆', 'Art Rock, Blues Rock', '3.18', '2021 专辑「飞狗」自序
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (366, '敷衍', '王菲', '中国', '大陆', 'Pop, Trip Hop, Adult Contemporary, Dream Pop', '3.76', '王菲 第十张粤语大碟《敷衍》
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (367, 'Tea with Flower Fragrance', '张福全', '中国', '大陆', 'Chinese Folk Music', '3.5', '张福全1993年专辑《Tea with Flower Fragrance》，中国民谣/传统音乐。茶香花韵中的东方美学，传统旋律的精致呈现。', 0, '2025-08-27', NULL, '/covers/367-张福全-Tea with Flower Fragrance.jpg', '59:59', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1993, 'Folk', NULL, 208, 196, 3, NULL, NULL, NULL, NULL, NULL, '7c704f8c-aa1b-4831-8951-02755e3755ef', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (368, '单身逃亡', '郑智化', '中国', '台湾', 'Pop', NULL, '《单身逃亡》是郑智化的第二张个人专辑，也是他在1990年加入可登唱片公司成为专职音乐人后的第一张专辑，这张专辑被认为是最具郑智化个人风格的唱片，他在音乐中叙述自己的成长和梦想，对生活热爱和自我孤立的矛盾，梦境的凄美和真实生命的孤独和逃亡等等，自身残疾的阴影在专辑内容中仍不时流露，进而转化为对青春的真实和残酷描述。唱片中歌曲主要是旋律简单的民谣作品，音乐真挚动人又带有淡淡的伤感，很受年轻一代歌迷的喜爱。', 0, '2025-09-16', '可登有声', '/covers/368-郑智化-单身逃亡.jpg', '42:30', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1990, 'Pop', NULL, 286, NULL, 2, NULL, NULL, NULL, NULL, NULL, 'b08f795d-5604-4ab8-b260-a5e61d5d416a', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (369, '魔性的释放', '陈劲', '中国', '大陆', 'Rock', NULL, '2023年，2023年陈劲全新专辑《魔性的释放》热烈上线，在平静中呐喊，在隐秘处绝响。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (370, '3', 'Carsick Cars', '中国', '大陆', 'Indie Rock, Noise Pop, Jangle Pop', '3.36', '3 (three) is a number, numeral and digit. It is the natural number following 2 and preceding 4, and is the smallest odd prime number and the only prime preceding a square number.', 0, '2025-09-16', '兵马司唱片', '/covers/370-Carsick Cars-3.jpg', '53:48', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2014, 'Rock,Pop', NULL, 34, 197, 17, NULL, NULL, NULL, NULL, NULL, '7c5737c4-9ceb-41e6-807e-9aaf27849f8c', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (371, '口', 'Carsick Cars', '中国', '大陆', 'Indie Rock,Noise Pop,Post-Rock,Post-Punk', '3.49', '国际，2021', 0, '2025-08-08', '兵马司唱片', '/covers/371-Carsick Cars-口.jpg', '46:06', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2024, 'Rock', NULL, 34, 198, 1, NULL, NULL, NULL, NULL, NULL, 'acccdd79-9224-4a90-bc63-7581eaf75830', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (372, 'Cest La Vie', '自然卷', '中国', '台湾', 'Indie Pop', '3.49', '2004年，风和日丽，与专辑同名歌曲"C‘est La Vie"更以跳跃的节奏轻松道出生活不过就是这样，「C‘est la vie，就这样喝个啤酒抽个香烟就没了，时钟滴滴答滴滴答答答', 0, '2025-10-22', '風和日麗唱片行 A Good Day Records', '/covers/372-自然卷-Cest La Vie.jpg', '44:39', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2004, 'Pop', NULL, 259, 44, 2, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (373, '惊喜', 'Beyond', '中国', '香港', 'Pop Rock, Alternative Rock', '3.2', '国际，2021', 0, '2025-10-22', 'Rock Records', '/covers/373-Beyond-惊喜.jpg', '44:21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1997, 'Rock', NULL, 20, 199, 1, NULL, NULL, NULL, NULL, NULL, '1dbe042a-382b-43b0-9cb4-0034daf5ff1a', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (374, 'Wish', 'The Cure', '英国', '伦敦', 'Alternative Rock', '3.78', 'If Wishes Could Kill (Korean: 기리고) is a 2026 South Korean young adult horror television series written by Park Joong-seop, directed by Park Youn-seo and starring Jeon So-young, Kang Mi-na, Baek Sun-ho, Hyun Woo-seok, and Lee Hyo-je. The series follows five high school students who must uncover the truth behind "Girigo", a mysterious wish-granting application after it begins predicting their sudden deaths. It was released on Netflix on April 24, 2026.', 0, '2025-10-22', 'Fiction', '/covers/374-The Cure-Wish.jpg', '65:53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1992, 'Rock', 'The Cure, David M. Allen', 138, 5, 1, NULL, NULL, NULL, 8.4, 'https://pitchfork.com/reviews/albums/the-cure-wish/', '0d5f0ccc-e41a-451d-8845-4675921982cc', 'active');
