INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (424, '成长小说', '海朋森', '中国', NULL, 'Rock', '0.0', '读完他离开时留下的信以后已是黄昏，她定了定神，有些惊讶地发现自己已经走了这么远的路。天色也慢慢暗下来了，她便开始往回走。 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (425, '灰太阳', '施鑫文月', '中国', NULL, NULL, '0.0', '灰太阳，顾名思义，雾里泛灰的太阳。成都的冬季来了，挂在天上。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (426, '巴蜀文艺复兴：第一章', '施鑫文月', '中国', NULL, NULL, '0.0', '2021年，第四音乐，——施鑫文月签约第四音乐首张个人专辑《巴蜀文艺复兴》——
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (427, '巴蜀文艺复兴：第二章', '施鑫文月', '中国', NULL, NULL, '0.0', '2023年，第四音乐，天涯虽大，一个人无论走到哪，ta的身上永远会流淌着故乡的血液。有时，当终其一生对自我身份的寻觅看似漫漫无果，蓦然回首，答案或许一直就藏在最熟悉的街巷深处。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (428, '生活麻辣烫', '王齐铭', '中国', NULL, NULL, '0.0', '“观众朋友大家好！你现在正在收看的是——重庆电视台《时尚频道》为你播出的《生活麻辣烫》！”
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (429, '精气神', '梁博', '中国', NULL, NULL, '0.0', '精：血脉中传承的坚韧，如同农民耕耘，种子深埋土壤，赤诚向下扎根的生存信仰。
