INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (431, '月下世界', '天鹅与花朵', '中国', NULL, NULL, '0.0', '黄昏切割日夜，也是逢魔与被诅咒的时刻。黄昏的美，是美一点点被摧毁，当认知与原则像日光一样破碎，放弃清醒，一只脚便踏入了月下的世界。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (432, '遇雨而生', '天鹅与花朵', '中国', NULL, NULL, '0.0', '如果所有魔法的出现都有预兆，那雨的下落，对于群山包围中的那座小城来说，是最常见的奇迹和魔法。而这张歌集，也是为了小县城中那些残破而细碎的幻想和浪漫而生，他们像雨点和雾气，装点着破败小城，给我们平淡无奇的生活蒙上一层神话的淡淡光晕。 在林地和山间的寻菌者，流连在时间的 迷 宫中，一点点收集这些转瞬即逝的云朵，小心翼翼的放置，直到有一刻可以将它们全部呈现。 天鹅与花朵是一支成立于四川成都的民谣计划，《遇雨而生》是他们的第一张全长专辑，实体唱片由上海的泛黑厂牌蔓延唱片发行，在早先的暗色民谣基础上，编织了些许氛围音乐的元素，共含8首作品。 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (433, 'Itinerary', 'Jo''s Moving Day', '中国', NULL, 'Rock', '0.0', 'The Antonine Itinerary (Latin: Itinerarium Antonini Augusti, "Itinerary of the Emperor Antoninus") is an itinerarium, a register of the stations and distances along various roads. Seemingly based on official documents, possibly in part from a survey carried out under Augustus, it describes the roads of the Roman Empire. Owing to the scarcity of other extant records of this type, it is a valuable historical record.', 0, NULL, '生煎唱片', '/covers/433-Jos-Moving-Day-Itinerary.jpg', '37:14', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2021, 'Shoegaze', NULL, 72, NULL, NULL, 3.59, 0, '', NULL, NULL, '797447a0-1620-4c9e-8303-eb5764bafb86', 'active');
