INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (438, 'Jessica Pratt', 'Asher White', '美国', NULL, 'Folk, World, & Country', '3.36', 'Jessica Pratt is the debut studio album by American folk singer-songwriter Jessica Pratt. It was released on November 20, 2012 through Darker My Love guitarist Tim Presley''s record label, Birth Records. Produced by Craig Gotsill, the album features the songs that were originally recorded in 2007 over analogue tape.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (439, '木马 (Muma)', '木马 [Muma]', '中国', NULL, 'Rock', '0.0', '2026年，我的AI音乐创作集。探索声音的无限可能，留住每一份听觉惊喜。', 0, NULL, 'Badhead', '/covers/439-Muma-Muma.jpg', '55:07', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.44, 1999, NULL, NULL, 222, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5ec97319-6c87-46c6-9788-5a8594d066ab', 'active');
