INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (443, 'She Came Back From the Square', '海朋森', '中国', NULL, 'Rock', '0.0', '海朋森2018年专辑《She Came Back From the Square》，中国独立摇滚/后朋克。南京独立场景代表，冷静叙事中的社会观察与女性声音。', 0, NULL, 'Maybe Mars', '/covers/443-海朋森-She Came Back From the Square.jpg', '24:41', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.13, 2018, 'Alternative Rock', NULL, 235, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'bf5a0974-887a-4e1e-b38f-7f9efd53bd8f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (444, '嘎调', '嘎调 [The Gar]', '中国', NULL, 'Rock, Pop', '0.0', '2009年，兵马司唱片/Indie Works，“中文”，“尖叫”，很多观众是通过这两个词语来熟悉嘎调，在兵马司旗下的后No Beijing乐队中，只有嘎调仍在坚持只用母语歌唱。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (445, '城市天气的航行 (City Weather Sailing)', 'P.K. 14', '中国', NULL, 'Rock', '0.0', 'P.K.14 2008年录音室专辑。风格：中国摇滚、摇滚；关联：后朋克、朋克、独立摇滚、另类摇滚、新浪潮。郭佳评：「这是一张宏大的作品，也是他们最为好听的一次尝试。」石田吉藏华语最佳500张第123位，郭佳最佳华语流行专辑2000s第261位。MusicBrainz: 53296f12-b5db-3ff9-97da-37bcacacd8b0。网易云ID：36722。', 0, NULL, 'Maybe Mars', '/covers/445-P.K. 14-城市天气的航行 (City Weather Sailing).jpg', '53:12', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.38, 2008, 'Post-Punk', NULL, 112, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'eb6dce0f-b5f1-4866-abf6-579d9a35256a', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (446, '我不要别的历史', '海朋森 [Hiperson]', '中国', NULL, NULL, '0.0', '2015年，兵马司唱片/Indie Works，《我不要别的历史》是来自成都的五人乐队海朋森（Hiperson）首张全长录音室专辑，由杨海崧在Psychic Kong录音棚于2014年7月录制完成，共11首歌', 0, NULL, NULL, '/covers/446-Hiperson-No-Need-For-Another-History.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.56, 2015, NULL, NULL, 236, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'abc05ce8-a063-43b8-860d-80c108347474', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (447, 'Honeyed and Killed', '刺猬 [Hedgehog]', '中国', NULL, NULL, '0.0', '2011年，Beijing Modern Sky Culture Development Co.,Ltd.，专辑录制于2010年4月，2011年4月正式发行，被认为是刺猬“青春三部曲”中的最后一部。整张唱片围绕“甜蜜与杀害”这一主题创作，歌曲关于爱情与死亡，毒品与政治', 0, NULL, NULL, '/covers/447-刺猬 [Hedgehog]-Honeyed and Killed.jpg', '41:45', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.52, 2011, NULL, NULL, 178, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (448, '共同的土地 A Mutual Ground', '缺省 [Default]', '中国', NULL, NULL, '0.0', '缺省[Default]2023年专辑《共同的土地 A Mutual Ground》，中国独立摇滚/后摇。在共同语境下寻找声音的落脚点，器乐与人声的交织。', 0, NULL, NULL, '/covers/448-缺省 [Default]-共同的土地 A Mutual Ground.jpg', '43:29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.46, 2023, NULL, NULL, 254, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1059acea-58e9-4ba4-843b-3b3648d9f45e', 'active');
