INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (451, '乌鸦谷 - 晕晕众生,命命相连 (Crow Valley - It''s All Connected)', '刺猬 [Hedgehog]', '中国', NULL, NULL, '0.0', '2022年，太合乐人/Indie Works，很久很久以前，人们把密函绑在乌鸦的腿上，隔空传书。乌鸦们驮着信息，飞渡城堡、钟楼、森林和莽原……
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (452, 'The Jester Race', 'In Flames', '德国', NULL, 'Rock', '0.0', 'The Jester Race is the second studio album by Swedish heavy metal band In Flames, released in February 1996. It is the first album to feature Anders Fridén as the band''s vocalist, Björn Gelotte as the drummer, and Jester Head as the band''s mascot.', 0, NULL, 'Nuclear Blast', '/covers/452-In Flames-The Jester Race.jpg', '40:09', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1996, 'Melodic Death Metal', NULL, 67, NULL, NULL, 3.74, 0, '', NULL, NULL, '08b7212c-def7-3a3e-bedf-19db3e3b023b', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (454, 'Loveless', 'My Bloody Valentine', '爱尔兰', NULL, 'Rock', '0.0', 'Loveless is the second studio album by the Irish rock band My Bloody Valentine. It was released on 4 November 1991 in the United Kingdom by Creation Records and in the United States by Sire Records. The album was recorded between February 1989 and September 1991, with vocalist and guitarist Kevin Shields leading sessions and experimenting with glide guitar technique, non-standard tunings, digital sampling, and meticulous production methods. The band recorded at nineteen different studios and hired several engineers during the album''s prolonged recording, with its final production cost rumoured to have reached £250,000 (equivalent to £580,000 in October 2025), though this number is disputed by Shields. 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (455, 'Ram', 'Paul McCartney', '美国', NULL, 'Rock', '0.0', 'Ram, ram, or RAM commonly refers to:
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (456, 'All Things Must Pass', 'George Harrison', '美国', NULL, 'Rock', '0.0', 'All Things Must Pass is the third studio album by the English rock musician George Harrison. Released as a triple album in November 1970, it was Harrison''s first solo work after the break-up of the Beatles in April that year. It includes the hit singles "My Sweet Lord" and "What Is Life", as well as songs such as "Isn''t It a Pity" and the title track that had been overlooked for inclusion on releases by the Beatles. The album reflects the influence of Harrison''s musical activities with artists such as Bob Dylan, the Band, Delaney & Bonnie and Friends and Billy Preston during 1968–70, and his growth as an artist beyond his supporting role to former bandmates John Lennon and Paul McCartney. All Things Must Pass introduced Harrison''s signature slide guitar sound and the spiritual themes present throughout his subsequent solo work. The original vinyl release consisted of two LPs of songs and a third disc of informal jams titled Apple Jam. Several commentators interpret Barry Feinstein''s album cover photo, showing Harrison surrounded by four garden gnomes, as a statement on his independence from the Beatles.', 0, NULL, 'Apple Records', '/covers/456-George Harrison-All Things Must Pass.jpg', '103:33', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1970, 'Pop Rock', NULL, 62, NULL, NULL, 4.13, 0, '', 9, 'https://pitchfork.com/reviews/albums/22037-all-things-must-pass/', '07d51bc7-64c9-3fba-b6fc-0695f6e8d6a4', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (457, 'Dirt', 'Alice In Chains', '英国', NULL, 'Rock', '0.0', 'Dirt is the second studio album by the American rock band Alice in Chains, released on September 29, 1992, by Columbia Records. It was the band''s last album recorded with all four original members, as bassist Mike Starr was fired in January 1993 during the tour to support the album. The majority of the songs were written by guitarist Jerry Cantrell, but for the first time, vocalist Layne Staley wrote two songs by himself, featuring himself on guitar. The track "Iron Gland" features Tom Araya from Slayer on vocals. The album''s lyrics explore depression, pain, anger, anti-social behavior, relationships, drug addiction, war, death, and other emotionally charged topics.', 0, NULL, 'Columbia', '/covers/457-Alice In Chains-Dirt.jpg', '57:34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2009, 'Alternative Metal', NULL, 8, NULL, NULL, 3.76, 0, '', 8.7, 'https://pitchfork.com/reviews/albums/alice-in-chains-dirt/', '2f0f5a06-f592-46fb-a782-6437ae81f4b9', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (458, 'Hasta la raíz', 'Natalia Lafourcade', '墨西哥', NULL, 'Rock', '0.0', 'Hasta la Raíz (transl. To the Root) is the fifth studio album by Mexican singer-songwriter Natalia Lafourcade, released on March 17, 2015, through Sony Music Mexico. After the success of her previous album, Mujer Divina – Homenaje a Agustín Lara (transl. Divine Woman – A Homage to Agustin Lara), a tribute to Mexican singer-songwriter Agustín Lara, Lafourcade decided to record an album with original recordings. Lafourcade spent three years writing the songs and searching for inspiration in different cities, resulting in songs that express very personal feelings regarding love. The record was produced by Lafourcade, with the assistance of Argentinian musician Cachorro López and Mexican artist Leonel García.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (459, 'Soldatenschicksale', 'Kanonenfieber', '德国', NULL, 'Rock', '0.0', 'Kanonenfieber (English: Cannon Fever) is an anonymous German blackened death metal band from Bamberg. Their lyrics are generally centered around World War I.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (460, 'Cancionera', 'Natalia Lafourcade', '墨西哥', NULL, 'Jazz', '0.0', 'Cancionera (transl. Songstress) is the eleventh studio album by Mexican singer-songwriter Natalia Lafourcade. It was released on 24 April 2025 on Sony Music Mexico. For this work, Lafourcade presents her artistic alter ego: "La Cancionera" (The Songstress).', 0, NULL, 'Sony Music', '/covers/460-Natalia Lafourcade-Cancionera.jpg', '65:34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.75, 2025, 'Son', NULL, 102, NULL, NULL, 3.19, 0, '', NULL, NULL, '939bc6fb-68b0-4884-8acd-c5db1d8df993', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (461, 'Daydream Nation', 'Sonic Youth', '美国', NULL, 'Rock', '0.0', 'Daydream Nation is the fifth studio album by American alternative rock band Sonic Youth, released on October 18, 1988. The band recorded the album between July and August 1988 at Greene St. Recording in New York City, and it was released by Enigma Records as a double album. It would be the band''s only release on Enigma, as they would sign with Geffen Records for their next album. 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (462, 'Misery Is a Butterfly', 'Blonde Redhead', '美国', NULL, 'Rock', '0.0', 'Misery Is a Butterfly is the sixth studio album by American alternative rock band Blonde Redhead. The album was released on March 15, 2004, by 4AD. The album''s lyrics and imagery reflect on a horseback accident Makino suffered in 2003, which required facial reconstructive surgery and months of rehabilitation, and caused her mental distress. The tracks "Elephant Woman" and "Equus" are more directly about the incident.
