INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (469, '两语', '文雀 [Sparrow]', '中国', NULL, NULL, '0.0', '2026年，Beijing Modern Sky Culture Development Co.,Ltd.，语，由“言”与“吾”构成，是一场发生在自我与世界之间往复不止的对谈，它发生在水流的方向里，发生在鸟鸣的间隙中，发生在潮湿的土壤与季节的更替里。
