INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (486, 'Some Things Never Leave', 'Annabelle Dinda', '美国', NULL, 'Rock', '0.0', 'Some Things Never Leave You (STNLY) is the fourth studio album by American alternative rock band Sherwood. The album was released on June 17, 2016.', 0, NULL, 'Not On Label (Annabelle Dinda Self-released)', '/covers/486-Annabelle Dinda-Some Things Never Leave.jpg', '40:25', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2.93, 2026, 'Folk Rock', NULL, 13, NULL, NULL, 2.81, 0, '', NULL, NULL, '49ac576d-5eda-41bd-969f-d730e78170a8', 'active');
