INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (488, 'Singin'' to an Empty Chair', 'Ratboys', '美国', NULL, 'Rock', '0.0', 'Singin'' to an Empty Chair is the sixth studio album from American rock band Ratboys, released on February 6, 2026 through New West Records.', 0, NULL, 'New West Records', '/covers/488-Ratboys-Singin to an Empty Chair.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2026, 'Indie Rock', NULL, 123, NULL, NULL, 3.39, 0, '', 8.4, 'https://pitchfork.com/reviews/albums/ratboys-singin-to-an-empty-chair/', 'b1645f20-eced-449d-8cab-045c630f9f24', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (489, 'The Sound of One Car Crashing', 'threadbaron', '中国', NULL, NULL, '0.0', 'Withered is the debut and only  studio album by American singer-songwriter D4vd, released on April 25, 2025. Before the album, D4vd gained recognition with his debut single "Romantic Homicide" and signed with Darkroom and Interscope Records. He released two EPs, Petals to Thorns and The Lost Petals in 2023, collaborating with producers such as Tyler Spry, Ryan Tedder, and Harry Charles, among others. The album delves into themes of heartbreak, emotional isolation, and personal growth. Following the discovery of Celeste Rivas Hernandez''s remains in an automobile registered to D4vd, the album''s promotional tour was cut short, and a planned deluxe edition was shelved.', 0, NULL, NULL, '/covers/489-threadbaron-The Sound of One Car Crashing.jpg', '16:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2024, NULL, NULL, 147, NULL, NULL, 3.36, 0, '', NULL, NULL, '85f53e3b-6e36-450f-8348-2e0ab09a3df9', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (490, 'Peanut', 'Otto Benson', '美国', NULL, 'Electronic', '0.0', 'Mr. Peanut is the advertising logo and mascot of Planters, an American snack-food company owned by Hormel. He is depicted as an anthropomorphic peanut in its shell, wearing the formal clothing of an old-fashioned gentleman, with a top hat, monocle, white gloves, spats, and cane. He is reported to be of British heritage and has the proper name of Bartholomew Richard Fitzgerald-Smythe.', 0, NULL, 'Palto Flats', '/covers/490-Otto Benson-Peanut.jpg', '38:44', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2025, 'Experimental', NULL, 110, NULL, NULL, 4, 0, '', 8.2, 'https://pitchfork.com/reviews/albums/otto-benson-peanut/', '1f3ca0d6-cc50-4e5b-9b4f-37353248a782', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (491, 'Days of Ash', 'U2', '美国', NULL, 'Rock', '0.0', 'Days of Ash is an EP by the Irish rock band U2. Produced by Jacknife Lee, it was released on 18 February 2026 through Island Records, coinciding with Ash Wednesday. The six-track EP contains five new songs, including protest songs addressing Russia''s invasion of Ukraine, the killings of Minneapolis woman Renée Good, Iranian teenager Sarina Esmailzadeh, and Palestinian activist Awdah Hathaleen, as well as a poem by Israeli poet Yehuda Amichai set to music. It was the first collection of newly written songs to be released by the band since their 2017 studio album Songs of Experience. The EP release was accompanied by a lyric video for each track and a one-off special edition of the group''s official magazine, Propaganda.  Less than two months later, the group followed it up with the surprise release of another six-track EP, Easter Lily, in April 2026.', 0, NULL, 'Island Records', '/covers/491-U2-Days of Ash.jpg', '23:30', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2.64, 2026, NULL, NULL, 150, NULL, NULL, 2.68, 0, '', 6, 'https://pitchfork.com/reviews/albums/u2-days-of-ash-ep/', '0cd25b8d-891d-418c-b1a7-d0eeceadd1d9', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (492, 'You Are in My Dreams', 'Kisses', '美国', NULL, 'Rock', '0.0', '英国，2014', 0, NULL, 'Bedroom Suck Records', '/covers/492-Kisses-You Are in My Dreams.jpg', '45:34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.47, 2026, 'Folk', NULL, 80, NULL, NULL, 3.56, 0, '', NULL, NULL, '76d86cb5-5bbe-4a02-9087-ea39e8df5ecd', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (493, 'Nothing''s About to Happen to Me', 'Mitski', '美国', NULL, 'Rock', '0.0', 'Nothing''s About to Happen to Me is the eighth studio album by the American singer-songwriter Mitski, released on February 27, 2026, through Dead Oceans.', 0, NULL, 'Dead Oceans', '/covers/493-Mitski-Nothings About to Happen to Me.jpg', '34:23', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.45, 2026, 'Indie Rock', NULL, 96, NULL, NULL, 3.39, 0, '', 7.7, 'https://pitchfork.com/reviews/albums/mitski-nothings-about-to-happen-to-me/', '059bdabe-9d74-4b7b-90f2-c424e82f2998', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (494, 'The Mountain', 'Gorillaz', '美国', NULL, 'Electronic', '0.0', 'The Mountain (title written in Devanagari as पर्वत, parvata, "mountain" in Sanskrit) is the ninth studio album by British virtual band Gorillaz. It was released on 27 February 2026 through their own label, Kong, with distribution by Sony Music subsidiary the Orchard. It is the first Gorillaz album to be released without the participation of Parlophone.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (495, 'The Apple Tree Under the Sea', 'Hemlocke Springs', '美国', NULL, 'Electronic', '0.0', 'The Apple Tree Under the Sea (stylized in lowercase) is the debut studio album by American singer and songwriter Hemlocke Springs, released independently on February 13, 2026.', 0, NULL, 'AWAL Recordings', '/covers/495-Hemlocke Springs-The Apple Tree Under the Sea.jpg', '33:15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.52, 2026, 'Alt-Pop', NULL, 66, NULL, NULL, 3.5, 0, '', NULL, NULL, '42bcad2d-ff06-4ff3-9b8a-f41d8b1d10de', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (496, 'Blame the Clown', 'Twisted Teens', '美国', NULL, 'Rock', '0.0', '国际，2011', 0, NULL, 'Chain Smoking Records', '/covers/496-Twisted Teens-Blame the Clown.jpg', '30:25', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.39, 2026, 'Punk', NULL, 149, NULL, NULL, 3.42, 0, '', 8.2, 'https://pitchfork.com/reviews/albums/twisted-teens-blame-the-clown/', '1aa47da7-16ba-471e-986b-880dbbc32a9b', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (497, 'It''s Fine to Dream', 'You Are an Angel', '美国', NULL, 'Electronic', '0.0', 'Angel Reese (born May 6, 2002) is an American professional basketball player for the Atlanta Dream of the Women''s National Basketball Association (WNBA) and Rose of Unrivaled. Nicknamed the "ATL Barbie", she played college basketball for the Maryland Terrapins and LSU Tigers. She is considered one of the greatest rebounders in WNBA history.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (498, 'Overspace & Supertime', 'Cryptic Shift', '美国', NULL, 'Rock', '0.0', 'Cryptic Shift (formerly stylized as Crÿptic Shift) is an English extreme metal band formed in Leeds, West Yorkshire in 2013. They have two EPs and two demos, with their debut album Visitations from Enceladus being released on 4 May 2020 through Blood Harvest records. In an article for The Quietus, the album was referred to as "damn near essential, and proof that [Britain] has a valid contribution to make to this new wave of progressive death metal".', 0, NULL, 'Metal Blade Records', '/covers/498-Cryptic Shift-Overspace & Supertime.jpg', '78:56', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.68, 2026, 'Thrash', NULL, 40, NULL, NULL, 3.63, 0, '', NULL, NULL, '12b677ba-3f5d-47b0-b7d0-937067469dac', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (499, 'Help(2)', 'Various Artists War Child Records', '美国', NULL, 'Electronic', '0.0', 'Help! is the fifth studio album by the English rock band the Beatles and the soundtrack to the film Help!. It was released on 6 August 1965 by Parlophone. Seven of the fourteen songs, including the singles "Help!" and "Ticket to Ride", appeared in the film and take up the first side of the vinyl album. The second side includes "Yesterday", the most-covered song ever written. The album was met with favourable critical reviews and topped the Australian, German, British and American charts.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (500, 'U', 'underscores', '美国', NULL, 'Electronic', '0.0', 'Enclosed Alphanumeric Supplement is a Unicode block consisting of Latin alphabet characters and Arabic numerals enclosed in circles, ovals or boxes, used for a variety of purposes. It is encoded in the range U+1F100–U+1F1FF in the Supplementary Multilingual Plane.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (501, 'Girlfriend', 'Grace Ives', '美国', NULL, 'Pop', '0.0', 'A girlfriend is a woman who is a friend, acquaintance or partner to the speaker, usually a female companion with whom one is platonically, romantically, or sexually involved. In a romantic context, this normally signifies a committed relationship where the individuals are not married. Other titles, for example "wife", usually signify that the individuals are legally married.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (502, 'Everything', 'Black Sea Dahu', '美国', NULL, 'Pop', '0.0', 'Everything, every-thing, or every thing, is all that exists, and is opposite of nothing. As this encompasses the totality of things relevant to some subject matter, it can be understood in many different ways. 
