INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (505, 'An Undying Love for a Burning World', 'Neurosis', '美国', NULL, 'Rock', '0.0', 'An Undying Love for a Burning World is the twelfth studio album by American post-metal band Neurosis. Their first album in 10 years, it was released, with no prior announcement, on March 20, 2026, via the band''s own record label, Neurot Recordings. It is the band''s first album with vocalist/guitarist Aaron Turner (formerly of the band Isis), replacing founder Scott Kelly who was fired from the band for domestic violence in 2019, as well as their first album since Through Silver in Blood (1996) that is not recorded by Steve Albini, who died in 2024.', 0, NULL, 'Neurot Recordings', '/covers/505-Neurosis-An Undying Love for a Burning World.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, 2026, 'Post-Metal', NULL, 103, NULL, NULL, 3.84, 0, '', 8.3, 'https://pitchfork.com/reviews/albums/neurosis-an-undying-love-for-a-burning-world', '55e6db80-da4d-4b86-930f-c09f2ec1b093', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (506, 'It''s the Long Goodbye', 'The Twilight Sad', '美国', NULL, 'Electronic', '3.49', 'It''s the Long Goodbye is the sixth studio album by Scottish indie rock band the Twilight Sad, released by Rock Action Records on 27 March 2026. It is the band''s first studio album since 2019. Three singles preceded the album''s release, which was followed by nationwide tours of the United Kingdom and Europe. 
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (507, 'Creature of Habit', 'Courtney Barnett', '美国', NULL, 'Rock', '0.0', 'Creature of Habit is the fourth studio album by Australian singer-songwriter Courtney Barnett. It was announced in January 2026 and was released on 27 March 2026 by Mom + Pop Music.
