INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (513, 'American Football [LP4]', 'American Football', '美国', NULL, NULL, '0.0', 'American Football (also known as LP4) is the fourth studio album by American rock band American Football, released on May 1, 2026, via Polyvinyl Record Co. It is the band''s first studio album in nearly seven years, after 2019''s LP3.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (514, 'Train on the Island', 'Aldous Harding', '美国', NULL, 'Rock', '3.5', 'Train on the Island is the fifth studio album by the New Zealand indie folk singer-songwriter Aldous Harding, released on 8 May 2026 through Flying Nun Records in New Zealand and 4AD elsewhere. It was produced by longtime collaborator John Parish, and serves as the follow-up to Harding''s 2022 album Warm Chris. The album was preceded by the singles "One Stop", "Venus in the Zinnia", and "Coats".', 0, NULL, '4AD', '/covers/514-Aldous Harding-Train on the Island.jpg', '39:27', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3.55, 2026, 'Indie Rock', NULL, 7, NULL, NULL, 3.47, 0, '', 9, 'https://pitchfork.com/reviews/albums/aldous-harding-train-on-the-island/', '1d075851-a063-46ec-90d0-b4202c0c28b0', 'active');
