INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (517, '悲歌欢唱 Lamenting in Delight', '苏紫旭 & The Paramecia', '中国', '大陆', NULL, '3.5', '2026年，山川有灵，滋养了中国人的魂魄。历史有因，造就了我们如今的性格。而作为一名创作者，脚下的大地恰是我命数中该去历炼的红尘。
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (518, '告密的心 (The Tell-Tale Heart)', 'Tizzy Bac', '台湾', NULL, 'Electronic', '3.14', '国际，2011', 0, NULL, 'Wonder Music 彎的音樂', '/covers/518-Tizzy Bac-告密的心 (The Tell-Tale Heart).jpg', '72:17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2011, 'Folk Rock', NULL, 148, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '828511c7-9f32-411e-b986-c61e1fae33e3', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (519, 'Marathon', 'Maria BC', '美国', NULL, 'Rock', '3.47', 'The 46th London Marathon took place on 26 April 2026. The race was the third of seven World Major Marathon events and was a platinum label race. The route featured three separate starting points — one by Greenwich Park and two on Blackheath common — and ended on The Mall. Notable landmarks en route included Cutty Sark, Tower Bridge, Canary Wharf and Buckingham Palace. The race was historic for several reasons: it was the first marathon completed in under two hours, with Sabastian Sawe achieving a time of 1:59:30. The elite men''s runner-up, Yomif Kejelcha, also finished the race in under two hours (1:59:41), recording the fastest non-winning marathon time and the fastest marathon debut in history. Third-place finisher Jacob Kiplimo also finished under the previous world record. In the women''s elite field, Tigst Assefa set a new world record for a women-only marathon. As well as this, national records were set for both men and women, such as Peter Lynch''s 2:06:08 for Ireland, and Julia Paternain''s 2:25:47 for Uruguay.', 0, NULL, 'Sacred Bones Records', '/covers/519-Maria BC-Marathon.jpg', '43:55', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2026, 'Indie Rock', NULL, 89, NULL, NULL, 2.9, 0, '', 7.4, 'https://pitchfork.com/reviews/albums/maria-bc-marathon', 'fd71f94c-6899-45cf-ab1f-2c1add97358f', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (520, '如果看見地獄，我就不怕魔鬼', 'Tizzy Bac', '台湾', NULL, 'Pop', '3.39', '国际，2011', 0, NULL, 'Wonder Music 彎的音樂', '/covers/520-Tizzy Bac-如果看見地獄，我就不怕魔鬼.jpg', '71:45', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 2009, 'Indie Pop', NULL, 148, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '03863673-337c-4073-95f1-13337fc59057', 'active');
