INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (540, 'The Boys of Dungeon Lane', 'Paul McCartney', '英国', NULL, NULL, NULL, 'The Boys of Dungeon Lane is the twentieth solo studio album by English musician Paul McCartney, released on 29 May 2026 through Capitol Records. Co-produced with Andrew Watt in sessions dating back to 2021, it was announced on 26 March 2026 along with the release of its lead single, "Days We Left Behind". The second single, "Home to Us", is a duet with Ringo Starr.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (541, 'Chinese Football', 'Chinese Football', '中国', NULL, 'Midwest Emo, Math Pop, Math Rock, Post-Rock, Dream Pop', '3.45', 'Chinese Football is a Chinese indie rock and math rock band. It was founded in 2011, in Wuhan, China.  The band self publishes their music under Xu Bo''s own Wild Records label.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (542, 'Det hjemsokte hjertet', 'Panopticon', '挪威', NULL, 'Atmospheric Black Metal / Post-Metal', '3.84', 'Panopticon is an American black metal band founded by Austin Lunn in Louisville, Kentucky in 2007. The band''s music has been described as "wrenching in its intensity but also sweeping and spectacular" and "ideologically open-minded and musically progressive, tackling issues around self-identity, ecology, religion and politics." Lunn''s lyrical style has also been noted as "natural, organic, and methodical, masterful in its writing, fiery and alive in its execution."', 0, NULL, NULL, '/covers/542-Panopticon-Det hjemsokte hjertet.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, NULL, NULL, 113, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '595b17d1-c641-49dd-b51a-e583b00d6cfa', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (543, 'Wendy Eisenberg', 'Wendy Eisenberg', '美国', NULL, 'Singer-Songwriter / Chamber Folk', '3.47', 'Wendy Eisenberg is the eighth album by the American musician Wendy Eisenberg, released on April 3, 2026, through Joyful Noise Recordings. The album received universal acclaim from music critics.', 0, NULL, NULL, '/covers/543-Wendy Eisenberg-Wendy Eisenberg.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, NULL, NULL, 156, NULL, NULL, NULL, NULL, NULL, 8.2, 'https://pitchfork.com/reviews/albums/wendy-eisenberg-wendy-eisenberg', '739f507f-c4b0-413d-b9fa-ad5e7f789193', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (544, 'Vol.II', 'Angine de Poitrine', '法国', NULL, 'Math Rock', '3.58', 'Angine de Poitrine (Canadian French: [ãʒɪn də pwatʁɪn] ) is a Canadian rock duo formed in Saguenay, Quebec, in 2019. Its anonymous members perform under the pseudonyms Khn de Poitrine (guitar, bass) and Klek de Poitrine (drums). They are known for complex microtonal compositions in the style of math rock and experimental rock, and an absurdist image, with oversized papier-mâché masks and black-and-white polka-dotted costumes.
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (545, '幻象波谱星', '刺猬', '中国', '大陆', 'Dream Pop', NULL, '刺猬2014年专辑《幻象波谱星》，中国独立摇滚。子健与石璐的噪音流行实验，迷幻合成器与吉他噪音的碰撞。', 0, '2024-09-19', '摩登天空', '/covers/545-刺猬-幻象波谱星.jpg', '53:13:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2014-04-20', 'Rock', NULL, 177, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '24954554-fe4e-4397-a3b6-fa50b3fe3678', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (547, 'Teen of Denial (Joes Story)', 'Car Seat Headrest', '美国', NULL, 'Indie Rock', NULL, 'Teen of Denial (Joe''s Story) is the fourteenth studio album by American indie rock band Car Seat Headrest. A "re-imagination" of their tenth studio album Teens of Denial, it features a different album concept, lyrics, songs, mixing, and instrumentation overlaid on the original recordings. It was released by Matador Records on May 20, 2026, the tenth anniversary of Teens of Denial. The album received polarizing reactions from both critics and fans for its changes and deemed lack of necessity. Released a year after The Scholars, it marks the band''s shortest time between releases since 2016.', 0, NULL, NULL, '/covers/547-Car Seat Headrest-Teen of Denial (Joes Story).jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2016, 'Rock', NULL, 31, NULL, NULL, 2.34, 972, '', NULL, NULL, '5e6add3e-3733-4394-9ca1-ab1d31c5b5d6', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (548, 'Happy New Year', 'Gumshoes', '美国', NULL, 'chamber pop', NULL, 'Happy New Year, Colin Burstead is a 2018 British comedy-drama film written and directed by Ben Wheatley and featuring Neil Maskell as the title character, with Sarah Baxendale, Hayley Squires, Sam Riley, Doon Mackichan, Joe Cole, and Charles Dance also starring. It tells the story of a man who rents a country house for his extended family to celebrate the New Year. The film premiered at the 62nd BFI London Film Festival on 11 October 2018, and was distributed by BBC Films, airing on BBC Two on 30 December 2018.', 0, NULL, NULL, '/covers/548-Gumshoes-Happy New Year.jpg', '41:38', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'Rock', NULL, 314, NULL, NULL, 3.68, 392, '', NULL, NULL, '2da04588-588c-4daa-95e6-8c9d74c27f4c', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (549, 'In Blue Time', 'Ira Dot', '美国', NULL, 'chamber pop', NULL, 'Time is the continuous progression of existence that occurs in an apparently irreversible succession from the past, through the present, and into the future. Time dictates all forms of action, age, and causality, being a component quantity of various measurements used to sequence events, to compare the duration of events (or the intervals between them), and to quantify rates of change of quantities in material reality or in the conscious experience. Time is often referred to as the fourth dimension and the temporal dimension, in addition to the three spatial dimensions.
