INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (554, 'Teens of Style', 'Car Seat Headrest', '美国', NULL, NULL, NULL, 'Teens of Style is the ninth studio album/a compilation album by American indie rock band Car Seat Headrest, released on October 30, 2015. It is their first album as a full band, and first release under Matador Records. Intended as an introductory compilation for new listeners, it features reworked, newly recorded versions of songs originally released between 2010 and 2012, with the addition of one new composition.', 0, '2026-06-13', NULL, '/covers/554-Car Seat Headrest-Teens of Style.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2015, NULL, NULL, 31, NULL, NULL, 3.36, 8270, NULL, 8.1, 'https://pitchfork.com/reviews/albums/21121-teens-of-style', '1b0c7b7a-ebd3-47e7-a673-004513741cef', 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (555, 'you seem pretty sad for a girl so in love', 'Olivia Rodrigo', '美国', NULL, 'Pop', NULL, 'You Seem Pretty Sad for a Girl So in Love (stylized in all lowercase) is the third studio album by American singer-songwriter Olivia Rodrigo, released by Geffen Records on June 12, 2026. A concept album, it chronicles the rise and fall of a relationship and the gradual loss of self that unfolds along the way. The album features a guest appearance from English musician Robert Smith on the track "What''s Wrong with Me", marking the first time another artist has appeared on a Rodrigo studio album.
