INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (567, 'Dance Of Love', 'Tucker Zimmerman', NULL, NULL, NULL, NULL, 'Tucker Zimmerman, the Belgium-based/US-born octogenarian folk singer-songwriter, collaborates with Big Thief (Adrianne Lenker) on this 4AD release. A tender, wordly-wise meditation on love in all its forms — romantic, familial, and spiritual — recorded with the full Big Thief band plus Iji and Twain.', 0, NULL, '4AD', '/covers/567-Tucker Zimmerman-Dance Of Love.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2024, NULL, NULL, 321, NULL, NULL, NULL, NULL, NULL, 7.4, 'https://pitchfork.com/reviews/albums/tucker-zimmerman-dance-of-love/', NULL, 'active');
