INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (591, 'MAYHEM', 'Lady Gaga', 'US', 'North America', NULL, NULL, 'Lady Gaga 2025年专辑《MAYHEM》，美国流行。向工业与暗色流行倾斜，Gaga最具攻击性的一张。', 0, NULL, NULL, '/covers/591-Lady Gaga-MAYHEM.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2025, 'Pop', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, 'https://pitchfork.com/reviews/albums/lady-gaga-mayhem/', NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (592, 'Glutton For Punishment', 'Heartworms', 'UK', 'Europe', NULL, NULL, 'Heartworms 2025年专辑《Glutton For Punishment》，英国后朋克。Jojo Orme冰冷的合成器后朋克与暗色编曲。', 0, NULL, NULL, '/covers/592-Heartworms-Glutton For Punishment.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2025, 'Post-Punk', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (593, 'Doolittle', 'Pixies', 'US', NULL, 'Alternative Rock', NULL, 'Pixies 1989年专辑《Doolittle》，美国另类摇滚/噪音流行。定义quiet-LOUD结构的经典，影响Nirvana、Radiohead等无数乐队。收录Debaser、Here Comes Your Man、Monkey Gone to Heaven等名曲。Rolling Stone 500大专辑第226位。', 0, NULL, NULL, '/covers/593-Pixies-Doolittle.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1989, 'Alternative Rock / Noise Pop / Post-Punk', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (594, 'Rituals of Shame', 'Warning', NULL, NULL, NULL, NULL, 'Warning 2026年专辑《Rituals of Shame》，英国 doom metal。距经典debut《Watching from a Distance》(2006)整整20年，在南港前教堂录音棚录制5首沉重颂歌。', 0, NULL, NULL, '/covers/594-Warning-Rituals of Shame.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
INSERT INTO albums (album_id, album_name, artist, country, region, genre, rating, description, is_compilation, first_listen_date, release_company, cover_image_url, duration, composition_score, lyrics_meaning_score, creativity_score, arrangement_score, vocal_performance_score, instrumental_performance_score, sincerity_score, subjective_score, overall_score, release_year, style, producer, artist_id, genre_id, style_id, rym_rating, rym_ratings_count, rym_url, pitchfork_score, review_url, release_mbid, status) VALUES (595, 'Circadian Promise', 'Fires in the Distance', '美国', NULL, NULL, NULL, '美国康涅狄格州旋律死亡/厄运金属乐队Fires in the Distance第三张录音室专辑，Prosthetic Records发行。6首曲、49分钟。Yegor Savonin主创，键盘氛围感极强，旋律与死亡金属力量感平衡出色。Metallerium评分9.2/10。乐队风格受Paradise Lost、Swallow The Sun、Amorphis影响。', 0, NULL, NULL, '/covers/595-Fires in the Distance-Circadian Promise.jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'active');
